{"command":"cat > /tmp/brute_family.py <<'PY'
import hashlib, itertools, struct, json
targets={
 "": "e5cdd9412abe7d628d0550c1cee1cc51c01781eada1a718bf0a82d37b5ccf309",
 "a": "a5d428cdffc400ec303ed3f791e082632f38d2f22e459a10bebc8f516f83f658",
 "x": "e5b219ae025541e3ae41abf5d6077a76d23d79d7bdd909f04b934811a1117892",
 "b": "3c27da875dc4f90e38397240606398183c568737a57fd8302fa06cbc60bdd940",
 "ab": "cbc9514f43d8f5d840b09d0b1332137335a0c647a14f1096b4e7b3ef49c7ada2",
 "aa": "db91c7f683ab8228c80e337485b7ad16e18fe19f85f82228af412c76139c2992",
}
def all_hashes(b):
    if isinstance(b,str): b=b.encode()
    out={}
    out['sha256']=hashlib.sha256(b).hexdigest()
    out['sha3_256']=hashlib.sha3_256(b).hexdigest()
    out['sha512_256']=hashlib.new('sha512_256',b).hexdigest()
    out['blake2s']=hashlib.blake2s(b).hexdigest()
    out['blake2b32']=hashlib.blake2b(b,digest_size=32).hexdigest()
    out['shake256_32']=hashlib.shake_256(b).hexdigest(32)
    out['shake128_32']=hashlib.shake_128(b).hexdigest(32)
    out['sm3']=hashlib.new('sm3',b).hexdigest() if 'sm3' in hashlib.algorithms_available else ''
    out['sha256d_bin']=hashlib.sha256(hashlib.sha256(b).digest()).hexdigest()
    out['sha256d_hex']=hashlib.sha256(hashlib.sha256(b).hexdigest().encode()).hexdigest()
    # truncated sha512
    out['sha512_trunc']=hashlib.sha512(b).hexdigest()[:64]
    out['sha384_trunc']=hashlib.sha384(b).hexdigest()[:64]
    return out

def check(label, gen):
    # gen(text)->bytes
    ok=True
    for text,target in targets.items():
        b=gen(text)
        hs=all_hashes(b)
        # find which matches for first; need consistent algo across all
        matches=[k for k,v in hs.items() if v==target]
        if text=="":
            first_matches=matches
            if not matches:
                return
        else:
            if not any(m in first_matches for m in matches):
                return
    print("MATCH", label, first_matches)

# prefixes/suffixes dictionary
prefixes=["", "C:", "C: ", "C", "cloze", "Cloze", "CLOZE", "cloze:", "Cloze:", "cloze: ", "family", "Family", "card", "Card", "text", "text:", "Text", "\n", " ", "C: [", "[", "C:[", "C[]", "hashcards", "Hashcards", "hashcards:", "cloze\n", "Cloze\n", "C\n", "deck", "0", "1", "2", "\x00", "\x01", "\x02", "\xff"]
suffixes=["", "\n", "\r\n", " ", "]", "]\n", "\n\n", "\x00", "\xff", ":", "cloze", "Cloze", "0", "1"]
# Combinations prefix+text+suffix, also prefix+ '['+text+']'+suffix etc
for p,s in itertools.product(prefixes,suffixes):
    check(f"{p!r}+text+{s!r}", lambda t,p=p,s=s: (p+t+s).encode())
    check(f"{p!r}+[text]+{s!r}", lambda t,p=p,s=s: (p+"["+t+"]"+s).encode())

# Length prefix encodings
def make_len_gen(style, prefix=b"", suffix=b""):
    def gen(t):
        b=t.encode()
        if style=="u64le": lp=struct.pack("<Q", len(b))
        elif style=="u64be": lp=struct.pack(">Q", len(b))
        elif style=="u32le": lp=struct.pack("<I", len(b))
        elif style=="u32be": lp=struct.pack(">I", len(b))
        elif style=="u8": lp=bytes([len(b)])
        elif style=="usize_text": lp=str(len(b)).encode()
        elif style=="len_colon": lp=f"{len(b)}:".encode()
        elif style=="varint": lp=bytes([len(b)])  # for small same as u8
        else: lp=b""
        return prefix+lp+b+suffix
    return gen
for style in ["u64le","u64be","u32le","u32be","u8","usize_text","len_colon"]:
    for p_str in prefixes[:20]:
        for s_str in suffixes:
            check(f"len {style} p={p_str!r} s={s_str!r}", make_len_gen(style, p_str.encode(), s_str.encode()))
            # len after prefix but also suffix as 0xff etc - covered
    # suffix length etc
    check(f"text+len {style}", lambda t,style=style: t.encode() + (struct.pack("<Q",len(t)) if style=="u64le" else struct.pack(">Q",len(t)) if style=="u64be" else struct.pack("<I",len(t)) if style=="u32le" else b""))

# Rust Hash for String simulation: bytes + 0xff, length prefix u64 + bytes + 0xff, etc with discriminant prefixes 0..3 as u8/u32/u64
for disc_val in range(4):
    for disc_fmt in ["u8","u32le","u64le","u32be","u64be","none","text"]:
        for len_fmt in ["none","u64le","u32le","u64be","u8"]:
            for terminator in [b"", b"\xff", b"\x00", b"\n"]:
                def gen(t, dv=disc_val, df=disc_fmt, lf=len_fmt, term=terminator):
                    b=t.encode()
                    out=b""
                    if df=="u8": out+=bytes([dv])
                    elif df=="u32le": out+=struct.pack("<I",dv)
                    elif df=="u64le": out+=struct.pack("<Q",dv)
                    elif df=="u32be": out+=struct.pack(">I",dv)
                    elif df=="u64be": out+=struct.pack(">Q",dv)
                    elif df=="text": out+=str(dv).encode()
                    if lf=="u64le": out+=struct.pack("<Q",len(b))
                    elif lf=="u32le": out+=struct.pack("<I",len(b))
                    elif lf=="u64be": out+=struct.pack(">Q",len(b))
                    elif lf=="u8": out+=bytes([len(b)])
                    out+=b+term
                    return out
                check(f"rusthash disc{dv} {disc_fmt} len{len_fmt} term{terminator}", gen)

# JSON encodings
json_gens={
 "json_text_only": lambda t: json.dumps(t).encode(),
 "json_obj_text": lambda t: json.dumps({"text":t}, separators=(',',':')).encode(),
 "json_cloze_text": lambda t: json.dumps({"cloze":{"text":t}}, separators=(',',':')).encode(),
 "json_Cloze_text": lambda t: json.dumps({"Cloze":{"text":t}}, separators=(',',':')).encode(),
 "json_cloze_str": lambda t: json.dumps({"cloze":t}, separators=(',',':')).encode(),
 "debug_string": lambda t: f'"{t}"'.encode(),
 "rust_debug_cloze": lambda t: f'Cloze {{ text: "{t}" }}'.encode(),
}
for k,g in json_gens.items(): check(k,g)

# UTF16 etc
for enc in ['utf-16le','utf-16be','utf-32le']:
    check(f"enc {enc}", lambda t,enc=enc: t.encode(enc))
    check(f"enc {enc} bom/cloze", lambda t,enc=enc: ("cloze"+t).encode(enc))

print("done")
PY
python3 /tmp/brute_family.py
"}

