import subprocess, time, urllib.request, urllib.error, urllib.parse, os, sys, signal, re
class Drill:
    def __init__(self, directory, port=8199, extra_args=[]):
        self.port=port; self.base=f"http://127.0.0.1:{port}"
        self.proc=subprocess.Popen(["./executable","drill","--open-browser","false","--port",str(port)]+extra_args+[directory], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        for i in range(100):
            try:
                self.get("/"); break
            except Exception:
                if self.proc.poll() is not None:
                    out,err=self.proc.communicate(); raise RuntimeError(f"exit {self.proc.returncode} out={out} err={err}")
                time.sleep(0.05)
        else:
            raise RuntimeError("no server")
    def request(self, method, path, data=None, headers=None, raw=None):
        url=self.base+path
        if raw is not None:
            body=raw
        elif data is not None:
            body=urllib.parse.urlencode(data).encode()
        else:
            body=None
        req=urllib.request.Request(url, data=body, method=method, headers=headers or {})
        # don't follow? urllib follows 303 for POST? It converts? We'll handle by custom opener no redirect
        opener=urllib.request.build_opener(NoRedirect())
        try:
            resp=opener.open(req, timeout=5)
            return resp.status, dict(resp.headers), resp.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers), e.read()
    def get(self,path):
        return self.request("GET",path)
    def post_action(self, action):
        return self.request("POST","/",data={"action":action}, headers={"Content-Type":"application/x-www-form-urlencoded"})
    def get_text(self, path="/"):
        s,h,b=self.get(path); return s,h,b.decode('utf-8','replace')
    def act(self,action):
        s,h,b=self.post_action(action)
        return s,h,b
    def act_and_get(self,action):
        s,h,b=self.post_action(action)
        if s in (301,302,303):
