// A small Blake3 implementation written for the card hashes used by this
// program.  It supports the ordinary (unkeyed) 32-byte digest.

const IV: [u32; 8] = [
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
    0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
];
const MSG_PERMUTATION: [usize; 16] = [2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8];
const FLAG_CHUNK_START: u32 = 1;
const FLAG_CHUNK_END: u32 = 2;
const FLAG_PARENT: u32 = 4;
const FLAG_ROOT: u32 = 8;
const BLOCK_LEN: usize = 64;
const CHUNK_LEN: usize = 1024;

fn g(state: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize, mx: u32, my: u32) {
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(mx);
    state[d] = (state[d] ^ state[a]).rotate_right(16);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = (state[b] ^ state[c]).rotate_right(12);
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(my);
    state[d] = (state[d] ^ state[a]).rotate_right(8);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = (state[b] ^ state[c]).rotate_right(7);
}

fn round_fn(state: &mut [u32; 16], m: &[u32; 16]) {
    g(state, 0, 4, 8, 12, m[0], m[1]);
    g(state, 1, 5, 9, 13, m[2], m[3]);
    g(state, 2, 6, 10, 14, m[4], m[5]);
    g(state, 3, 7, 11, 15, m[6], m[7]);
    g(state, 0, 5, 10, 15, m[8], m[9]);
    g(state, 1, 6, 11, 12, m[10], m[11]);
    g(state, 2, 7, 8, 13, m[12], m[13]);
    g(state, 3, 4, 9, 14, m[14], m[15]);
}

fn permute(m: &mut [u32; 16]) {
    let old = *m;
    for i in 0..16 {
        m[i] = old[MSG_PERMUTATION[i]];
    }
}

fn compress(cv: &[u32; 8], block: &[u8; BLOCK_LEN], counter: u64, block_len: u32, flags: u32) -> [u32; 16] {
    let mut msg = [0u32; 16];
    for i in 0..16 {
        msg[i] = u32::from_le_bytes([
            block[i * 4],
            block[i * 4 + 1],
            block[i * 4 + 2],
            block[i * 4 + 3],
        ]);
    }
    let mut state = [
        cv[0], cv[1], cv[2], cv[3], cv[4], cv[5], cv[6], cv[7],
        IV[0], IV[1], IV[2], IV[3],
        counter as u32, (counter >> 32) as u32, block_len, flags,
    ];
    for round in 0..7 {
        round_fn(&mut state, &msg);
        if round != 6 {
            permute(&mut msg);
        }
    }
    let mut out = [0u32; 16];
    for i in 0..8 {
        out[i] = state[i] ^ state[i + 8];
        out[i + 8] = state[i + 8] ^ cv[i];
    }
    out
}

#[derive(Clone)]
struct Output {
    input_cv: [u32; 8],
    block: [u8; BLOCK_LEN],
    counter: u64,
    block_len: u32,
    flags: u32,
}

impl Output {
    fn chaining_value(&self) -> [u32; 8] {
        let out = compress(&self.input_cv, &self.block, self.counter, self.block_len, self.flags);
        let mut cv = [0u32; 8];
        cv.copy_from_slice(&out[..8]);
        cv
    }

    fn root_bytes(&self) -> [u8; 32] {
        let words = compress(
            &self.input_cv,
            &self.block,
            0,
            self.block_len,
            self.flags | FLAG_ROOT,
        );
        let mut bytes = [0u8; 32];
        for i in 0..8 {
            bytes[i * 4..i * 4 + 4].copy_from_slice(&words[i].to_le_bytes());
        }
        bytes
    }
}

fn chunk_output(chunk: &[u8], chunk_counter: u64) -> Output {
    let mut cv = IV;
    if chunk.is_empty() {
        return Output {
            input_cv: cv,
            block: [0u8; BLOCK_LEN],
            counter: chunk_counter,
            block_len: 0,
            flags: FLAG_CHUNK_START | FLAG_CHUNK_END,
        };
    }
    let blocks: Vec<&[u8]> = chunk.chunks(BLOCK_LEN).collect();
    let last_index = blocks.len() - 1;
    for (i, block) in blocks.iter().enumerate() {
        let mut padded = [0u8; BLOCK_LEN];
        padded[..block.len()].copy_from_slice(block);
        let start_flag = if i == 0 { FLAG_CHUNK_START } else { 0 };
        if i == last_index {
            return Output {
                input_cv: cv,
                block: padded,
                counter: chunk_counter,
                block_len: block.len() as u32,
                flags: start_flag | FLAG_CHUNK_END,
            };
        } else {
            let out = compress(&cv, &padded, chunk_counter, BLOCK_LEN as u32, start_flag);
            cv.copy_from_slice(&out[..8]);
        }
    }
    unreachable!()
}

fn parent_output(left: [u32; 8], right: [u32; 8]) -> Output {
    let mut block = [0u8; BLOCK_LEN];
    for i in 0..8 {
        block[i * 4..i * 4 + 4].copy_from_slice(&left[i].to_le_bytes());
        block[32 + i * 4..32 + i * 4 + 4].copy_from_slice(&right[i].to_le_bytes());
    }
    Output {
        input_cv: IV,
        block,
        counter: 0,
        block_len: BLOCK_LEN as u32,
        flags: FLAG_PARENT,
    }
}

pub fn hash(data: &[u8]) -> [u8; 32] {
    let chunks: Vec<&[u8]> = if data.is_empty() {
        vec![&[]]
    } else {
        data.chunks(CHUNK_LEN).collect()
    };
    let mut cv_stack: Vec<[u32; 8]> = Vec::new();
    for idx in 0..chunks.len() - 1 {
        let mut cv = chunk_output(chunks[idx], idx as u64).chaining_value();
        let mut total_chunks = idx + 1;
        while total_chunks % 2 == 0 {
            let left = cv_stack.pop().expect("cv stack underflow");
            cv = parent_output(left, cv).chaining_value();
            total_chunks /= 2;
        }
        cv_stack.push(cv);
    }
    let last = chunks.len() - 1;
    let mut out = chunk_output(chunks[last], last as u64);
    while let Some(left) = cv_stack.pop() {
        out = parent_output(left, out.chaining_value());
    }
    out.root_bytes()
}

#[cfg(test)]
mod tests {
    use super::hash;

    fn hex(data: &[u8]) -> String {
        data.iter().map(|b| format!("{:02x}", b)).collect()
    }

    #[test]
    fn known_vectors() {
        assert_eq!(hex(&hash(b"")), "af1349b9f5f9a1a6a0404dea36dcc9499bcb25c9adc112b7cc9a93cae41f3262");
        assert_eq!(hex(&hash(b"a")), "17762fddd969a453925d65717ac3eea21320b66b54342fde15128d6caf21215f");
        assert_eq!(hex(&hash(b"abc")), "6437b3ac38465133ffb63b75273a8db548c558465d79db03fd359c6cd5bd9d85");
        assert_eq!(hex(&hash(b"hello world")), "d74981efa70a0c880b8d8c1985d075dbcbf679b99a5f9914e5aaf96b831a9e24");
        assert_eq!(hex(&hash(&vec![b'x'; 1024])), "71c7a224be567fb9acd2c32f87359835322cf9241b9c01f247fff2b4bdabf644");
        assert_eq!(hex(&hash(&vec![b'x'; 1025])), "71b7ce25ca2144dcf4d7ed561d8a526bb7f7adaf8d10a124540d82bf113678c9");
    }
}
RS
cargo test --offline blake3::tests::known_vectors 2>&1 | tail -n 30

