{"command":"cat > src/error.rs <<'RS'
use std::collections::BTreeSet;
use std::fmt;
use std::io;
use std::path::StripPrefixError;

use crate::sqlite::SqliteError;

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct MissingMedia {
    pub media: String,
    pub file_path: String,
    pub line: usize,
}

#[derive(Debug)]
pub enum Error {
    DirectoryDoesNotExist,
    Io(io::Error),
    Rusqlite(SqliteError),
    DirectoryTraversal(walkdir::Error),
    StripPrefix(StripPrefixError),
    Parse {
        message: &'static str,
        file_path: String,
        line: usize,
    },
    FrontmatterNoClosing,
    Toml(toml::de::Error),
    MissingMedia(BTreeSet<MissingMedia>),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::DirectoryDoesNotExist => write!(f, "directory does not exist."),
            Error::Io(e) => write!(f, "I/O error: {e:#?}"),
            Error::Rusqlite(e) => write!(f, "rusqlite: {e:#?}"),
            Error::DirectoryTraversal(e) => write!(f, "directory traversal error: {e:#?}"),
            Error::StripPrefix(e) => write!(f, "Strip prefix error: {e:#?}"),
            Error::Parse {
                message,
                file_path,
                line,
            } => write!(f, "Parse error: {message} Location: {file_path}:{line}"),
            Error::FrontmatterNoClosing => {
                write!(f, "Frontmatter opening '---' found but no closing '---'")
            }
            Error::Toml(e) => write!(f, "Failed to parse TOML frontmatter: {e}"),
            Error::MissingMedia(items) => {
                writeln!(f, "Missing media files referenced in cards:")?;
                for item in items {
                    writeln!(
                        f,
                        "  - {} (referenced in {}:{})",
                        item.media, item.file_path, item.line
                    )?;
                }
                Ok(())
            }
        }
    }
}

impl std::error::Error for Error {}

impl From<io::Error> for Error {
    fn from(e: io::Error) -> Self {
        Error::Io(e)
    }
}

impl From<SqliteError> for Error {
    fn from(e: SqliteError) -> Self {
        Error::Rusqlite(e)
    }
}

impl From<walkdir::Error> for Error {
    fn from(e: walkdir::Error) -> Self {
        Error::DirectoryTraversal(e)
    }
}

impl From<StripPrefixError> for Error {
    fn from(e: StripPrefixError) -> Self {
        Error::StripPrefix(e)
    }
}

impl From<toml::de::Error> for Error {
    fn from(e: toml::de::Error) -> Self {
        Error::Toml(e)
    }
}

pub type Result<T> = std::result::Result<T, Error>;
RS

cat > src/sqlite.rs <<'RS'
//! A deliberately small wrapper around the system SQLite C library.
//!
//! The rest of the program needs prepared statements, a handful of column
//! conversions and error reports in the same shape as the error type used by
//! the original application, so those pieces are implemented here directly
//! with FFI rather than depending on a large database crate.

#![allow(non_camel_case_types)]

use std::ffi::{CStr, CString};
use std::fmt;
use std::os::raw::{c_char, c_int, c_uchar, c_void};
use std::path::Path;
use std::ptr;

#[repr(C)]
pub struct sqlite3 {
    _private: [u8; 0],
}

#[repr(C)]
pub struct sqlite3_stmt {
    _private: [u8; 0],
}

type SqliteDestructor = Option<extern "C" fn(*mut c_void)>;

extern "C" {
    fn sqlite3_open(filename: *const c_char, db: *mut *mut sqlite3) -> c_int;
    fn sqlite3_close(db: *mut sqlite3) -> c_int;
    fn sqlite3_prepare_v2(
        db: *mut sqlite3,
        sql: *const c_char,
        nbyte: c_int,
        stmt: *mut *mut sqlite3_stmt,
        tail: *mut *const c_char,
    ) -> c_int;
    fn sqlite3_step(stmt: *mut sqlite3_stmt) -> c_int;
    fn sqlite3_finalize(stmt: *mut sqlite3_stmt) -> c_int;
    fn sqlite3_bind_text(
        stmt: *mut sqlite3_stmt,
        index: c_int,
        text: *const c_char,
        n: c_int,
        destructor: *mut c_void,
    ) -> c_int;
    fn sqlite3_bind_int64(stmt: *mut sqlite3_stmt, index: c_int, value: i64) -> c_int;
    fn sqlite3_bind_double(stmt: *mut sqlite3_stmt, index: c_int, value: f64) -> c_int;
    fn sqlite3_bind_null(stmt: *mut sqlite3_stmt, index: c_int) -> c_int;
    fn sqlite3_column_type(stmt: *mut sqlite3_stmt, index: c_int) -> c_int;
    fn sqlite3_column_text(stmt: *mut sqlite3_stmt, index: c_int) -> *const c_uchar;
    fn sqlite3_column_bytes(stmt: *mut sqlite3_stmt, index: c_int) -> c_int;
    fn sqlite3_column_int64(stmt: *mut sqlite3_stmt, index: c_int) -> i64;
    fn sqlite3_column_double(stmt: *mut sqlite3_stmt, index: c_int) -> f64;
    fn sqlite3_errmsg(db: *mut sqlite3) -> *const c_char;
    fn sqlite3_extended_errcode(db: *mut sqlite3) -> c_int;
    fn sqlite3_error_offset(db: *mut sqlite3) -> c_int;
    fn sqlite3_last_insert_rowid(db: *mut sqlite3) -> i64;
    fn sqlite3_changes(db: *mut sqlite3) -> c_int;
}

const SQLITE_OK: c_int = 0;
const SQLITE_ROW: c_int = 100;
const SQLITE_DONE: c_int = 101;
const SQLITE_INTEGER: c_int = 1;
const SQLITE_FLOAT: c_int = 2;
const SQLITE_TEXT: c_int = 3;
const SQLITE_BLOB: c_int = 4;
const SQLITE_NULL: c_int = 5;

fn sqlite_transient() -> *mut c_void {
    // SQLITE_TRANSIENT is (void*)-1.
    (-1isize) as *mut c_void
}

fn error_code_name(code: c_int) -> &'static str {
    match code & 0xff {
        1 => "Unknown",
        2 => "InternalMalfunction",
        3 => "PermissionDenied",
        4 => "OperationAborted",
        5 => "DatabaseBusy",
        6 => "DatabaseLocked",
        7 => "OutOfMemory",
        8 => "ReadOnly",
        9 => "OperationInterrupted",
        10 => "SystemIoFailure",
        11 => "DatabaseCorrupt",
        12 => "NotFound",
        13 => "DiskFull",
        14 => "CannotOpen",
        15 => "FileLockingProtocolFailed",
        16 => "Empty",
        17 => "SchemaChanged",
        18 => "TooBig",
        19 => "ConstraintViolation",
        20 => "TypeMismatch",
        21 => "ApiMisuse",
        22 => "NoLargeFileSupport",
        23 => "AuthorizationForStatementDenied",
        24 => "Format",
        25 => "ParameterOutOfRange",
        26 => "NotADatabase",
        _ => "Unknown",
    }
}

#[derive(Clone)]
pub struct FfiError {
    pub code: c_int,
    pub extended_code: c_int,
    pub message: String,
}

#[derive(Clone)]
pub enum SqliteError {
    SqliteFailure {
        error: FfiError,
        message: Option<String>,
    },
    SqlInputError {
        error: FfiError,
        msg: String,
        sql: String,
        offset: i32,
    },
    FromSqlConversionFailure {
        index: usize,
        sql_type: SqlType,
        message: String,
    },
    IntegralValueOutOfRange {
        index: usize,
        value: i64,
    },
    InvalidType {
        index: usize,
        sql_type: SqlType,
    },
    QueryReturnedNoRows,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SqlType {
    Null,
    Integer,
    Real,
    Text,
    Blob,
}

impl SqlType {
    fn from_code(code: c_int) -> Self {
        match code {
            SQLITE_INTEGER => SqlType::Integer,
            SQLITE_FLOAT => SqlType::Real,
            SQLITE_TEXT => SqlType::Text,
            SQLITE_BLOB => SqlType::Blob,
            _ => SqlType::Null,
        }
    }
    fn name(self) -> &'static str {
        match self {
            SqlType::Null => "Null",
            SqlType::Integer => "Integer",
            SqlType::Real => "Real",
            SqlType::Text => "Text",
            SqlType::Blob => "Blob",
        }
    }
}

impl SqliteError {
    pub fn conversion(index: usize, sql_type: SqlType, message: String) -> Self {
        SqliteError::FromSqlConversionFailure {
            index,
            sql_type,
            message,
        }
    }
}

impl fmt::Debug for SqliteError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // The alternate ("{:#?}") rendering is what reaches the user at the
        // top level.  Match the shape of the debug output produced for the
        // corresponding database errors.
        match self {
            SqliteError::SqliteFailure { error, message } => {
                if f.alternate() {
                    write!(
                        f,
                        "SqliteFailure(\n    Error {{\n        code: {},\n        extended_code: {},\n    }},\n",
                        error_code_name(error.code),
                        error.extended_code
                    )?;
                    match message {
                        Some(message) => write!(f, "    Some(\n        {:?},\n    ),\n)", message),
                        None => write!(f, "    None,\n)"),
                    }
                } else {
                    write!(
                        f,
                        "SqliteFailure(Error {{ code: {}, extended_code: {} }}, {:?})",
                        error_code_name(error.code),
                        error.extended_code,
                        message
                    )
                }
            }
            SqliteError::SqlInputError {
                error,
                msg,
                sql,
                offset,
            } => {
                if f.alternate() {
                    write!(
                        f,
                        "SqlInputError {{\n    error: Error {{\n        code: {},\n        extended_code: {},\n    }},\n    msg: {:?},\n    sql: {:?},\n    offset: {},\n}}",
                        error_code_name(error.code),
                        error.extended_code,
                        msg,
                        sql,
                        offset
                    )
                } else {
                    write!(f, "SqlInputError {{ error: {:?}, msg: {:?}, sql: {:?}, offset: {} }}", error.code, msg, sql, offset)
                }
            }
            SqliteError::FromSqlConversionFailure {
                index,
                sql_type,
                message,
            } => {
                if f.alternate() {
                    write!(
                        f,
                        "FromSqlConversionFailure(\n    {},\n    {},\n    ErrorReport {{\n        message: {:?},\n    }},\n)",
                        index,
                        sql_type.name(),
                        message
                    )
                } else {
                    write!(f, "FromSqlConversionFailure({}, {}, ErrorReport {{ message: {:?} }})", index, sql_type.name(), message)
                }
            }
            SqliteError::IntegralValueOutOfRange { index, value } => {
                if f.alternate() {
                    write!(f, "IntegralValueOutOfRange(\n    {},\n    {},\n)", index, value)
                } else {
                    write!(f, "IntegralValueOutOfRange({}, {})", index, value)
                }
            }
            SqliteError::InvalidType { index, sql_type } => {
                if f.alternate() {
                    write!(
                        f,
                        "FromSqlConversionFailure(\n    {},\n    {},\n    InvalidType,\n)",
                        index,
                        sql_type.name()
                    )
                } else {
                    write!(f, "InvalidType({}, {})", index, sql_type.name())
                }
            }
            SqliteError::QueryReturnedNoRows => write!(f, "QueryReturnedNoRows"),
        }
    }
}

impl fmt::Display for SqliteError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{self:#?}")
    }
}

impl std::error::Error for SqliteError {}

pub type Result<T> = std::result::Result<T, SqliteError>;

#[derive(Clone, Debug)]
pub enum Value {
    Null,
    Integer(i64),
    Real(f64),
    Text(String),
}

pub struct Connection {
    db: *mut sqlite3,
}

// SQLite is used in serialized mode and this handle is only ever accessed
// behind the caller's mutex when shared.
unsafe impl Send for Connection {}

impl Drop for Connection {
    fn drop(&mut self) {
        if !self.db.is_null() {
            unsafe { sqlite3_close(self.db) };
            self.db = ptr::null_mut();
        }
    }
}

impl Connection {
    pub fn open(path: &Path) -> Result<Self> {
        // On Unix, paths are byte strings.  All paths reaching this point
        // have come through the command-line parser (valid UTF-8) joined to
        // a canonical directory, so a lossy C string matches what the
        // original program would construct from the same path.
        let c_path = CString::new(path.to_string_lossy().into_owned().into_bytes())
            .unwrap_or_else(|_| CString::new("").unwrap());
        let mut db: *mut sqlite3 = ptr::null_mut();
        let rc = unsafe { sqlite3_open(c_path.as_ptr(), &mut db) };
        if rc != SQLITE_OK {
            let error = if db.is_null() {
                FfiError {
                    code: rc,
                    extended_code: rc,
                    message: String::new(),
                }
            } else {
                unsafe { Self::ffi_error(db, rc) }
            };
            if !db.is_null() {
                unsafe { sqlite3_close(db) };
            }
            return Err(SqliteError::SqliteFailure {
                error,
                message: Some(format!(
                    "unable to open database file: {}",
                    path.display()
                )),
            });
        }
        Ok(Connection { db })
    }

    unsafe fn ffi_error(db: *mut sqlite3, code: c_int) -> FfiError {
        let extended = sqlite3_extended_errcode(db);
        let msg_ptr = sqlite3_errmsg(db);
        let message = if msg_ptr.is_null() {
            String::new()
        } else {
            CStr::from_ptr(msg_ptr).to_string_lossy().into_owned()
        };
        FfiError {
            code,
            extended_code: extended,
            message,
        }
    }

    fn last_error(&self, code: c_int) -> FfiError {
        unsafe { Self::ffi_error(self.db, code) }
    }

    fn prepare_error(&self, code: c_int, sql: &str) -> SqliteError {
        let error = self.last_error(code);
        let offset = unsafe { sqlite3_error_offset(self.db) };
        if offset >= 0 {
            SqliteError::SqlInputError {
                msg: error.message.clone(),
                error,
                sql: sql.to_string(),
                offset,
            }
        } else {
            SqliteError::SqliteFailure {
                message: Some(error.message.clone()),
                error,
            }
        }
    }

    pub fn prepare(&self, sql: &str) -> Result<Statement<'_>> {
        let c_sql = CString::new(sql).expect("SQL contains NUL byte");
        let mut stmt: *mut sqlite3_stmt = ptr::null_mut();
        let rc = unsafe {
            sqlite3_prepare_v2(
                self.db,
                c_sql.as_ptr(),
                -1,
                &mut stmt,
                ptr::null_mut(),
            )
        };
        if rc != SQLITE_OK {
            if !stmt.is_null() {
                unsafe { sqlite3_finalize(stmt) };
            }
            return Err(self.prepare_error(rc, sql));
        }
        Ok(Statement {
            conn: self,
            stmt,
            sql: sql.to_string(),
        })
    }

    /// Execute a sequence of semicolon-separated statements the way
    /// `execute_batch` does: prepare each remaining tail in turn.
    pub fn execute_batch(&self, sql: &str) -> Result<()> {
        let c_sql = CString::new(sql).expect("SQL contains NUL byte");
        let mut tail: *const c_char = c_sql.as_ptr();
        loop {
            let mut stmt: *mut sqlite3_stmt = ptr::null_mut();
            let mut next_tail: *const c_char = ptr::null();
            let rc = unsafe {
                sqlite3_prepare_v2(self.db, tail, -1, &mut stmt, &mut next_tail)
            };
            // Remaining SQL as a Rust string, for error reporting.
            let tail_str = unsafe {
                if tail.is_null() {
                    String::new()
                } else {
                    CStr::from_ptr(tail).to_string_lossy().into_owned()
                }
            };
            if rc != SQLITE_OK {
                if !stmt.is_null() {
                    unsafe { sqlite3_finalize(stmt) };
                }
                return Err(self.prepare_error(rc, &tail_str));
            }
            if stmt.is_null() {
                break;
            }
            let rc = unsafe { sqlite3_step(stmt) };
            let finalize_rc = unsafe { sqlite3_finalize(stmt) };
            if rc != SQLITE_DONE && rc != SQLITE_ROW {
                let code = if rc != SQLITE_OK { rc } else { finalize_rc };
                let error = self.last_error(code);
                return Err(SqliteError::SqliteFailure {
                    message: Some(error.message.clone()),
                    error,
                });
            }
            if next_tail.is_null() {
                break;
            }
            // Stop when the tail is only whitespace/semicolons left; the
            // next prepare call will observe that and return a null stmt.
            tail = next_tail;
            if unsafe { *tail } == 0 {
                break;
            }
        }
        Ok(())
    }

    pub fn execute(&self, sql: &str, params: &[Value]) -> Result<usize> {
        let mut stmt = self.prepare(sql)?;
        stmt.bind_all(params)?;
        stmt.step_done()?;
        Ok(unsafe { sqlite3_changes(self.db) } as usize)
    }

    pub fn last_insert_rowid(&self) -> i64 {
        unsafe { sqlite3_last_insert_rowid(self.db) }
    }

    pub fn query_all<T, F>(&self, sql: &str, params: &[Value], mut map: F) -> Result<Vec<T>>
    where
        F: FnMut(&Row<'_>) -> Result<T>,
    {
        let mut stmt = self.prepare(sql)?;
        stmt.bind_all(params)?;
        let mut out = Vec::new();
        loop {
            let rc = unsafe { sqlite3_step(stmt.stmt) };
            if rc == SQLITE_ROW {
                let row = Row { stmt: &stmt };
                out.push(map(&row)?);
            } else if rc == SQLITE_DONE {
                break;
            } else {
                return Err(stmt.step_error(rc));
            }
        }
        Ok(out)
    }

    pub fn query_one<T, F>(&self, sql: &str, params: &[Value], map: F) -> Result<Option<T>>
    where
        F: FnMut(&Row<'_>) -> Result<T>,
    {
        let mut v = self.query_all(sql, params, map)?;
        if v.is_empty() {
            Ok(None)
        } else {
            Ok(Some(v.remove(0)))
        }
    }

    pub fn query_scalar_i64(&self, sql: &str, params: &[Value]) -> Result<i64> {
        let value = self.query_one(sql, params, |row| row.get_i64(0))?;
        value.ok_or(SqliteError::QueryReturnedNoRows)
    }
}

pub struct Statement<'conn> {
    conn: &'conn Connection,
    stmt: *mut sqlite3_stmt,
    sql: String,
}

impl<'conn> Drop for Statement<'conn> {
    fn drop(&mut self) {
        if !self.stmt.is_null() {
            unsafe { sqlite3_finalize(self.stmt) };
            self.stmt = ptr::null_mut();
        }
    }
}

impl<'conn> Statement<'conn> {
    fn step_error(&self, code: c_int) -> SqliteError {
        let error = self.conn.last_error(code);
        SqliteError::SqliteFailure {
            message: Some(error.message.clone()),
            error,
        }
    }

    pub fn bind_all(&mut self, params: &[Value]) -> Result<()> {
        for (i, param) in params.iter().enumerate() {
            let index = (i + 1) as c_int;
            let rc = match param {
                Value::Null => unsafe { sqlite3_bind_null(self.stmt, index) },
                Value::Integer(v) => unsafe { sqlite3_bind_int64(self.stmt, index, *v) },
                Value::Real(v) => unsafe { sqlite3_bind_double(self.stmt, index, *v) },
                Value::Text(text) => {
                    let c_text = CString::new(text.as_str()).unwrap_or_else(|_| CString::new("").unwrap());
                    let rc = unsafe {
                        sqlite3_bind_text(
                            self.stmt,
                            index,
                            c_text.as_ptr(),
                            text.len() as c_int,
                            sqlite_transient(),
                        )
                    };
                    rc
                }
            };
            if rc != SQLITE_OK {
                return Err(self.step_error(rc));
            }
        }
        Ok(())
    }

    pub fn step_done(&mut self) -> Result<()> {
        let rc = unsafe { sqlite3_step(self.stmt) };
        if rc == SQLITE_DONE || rc == SQLITE_ROW {
            Ok(())
        } else {
            Err(self.step_error(rc))
        }
    }
}

pub struct Row<'stmt> {
    stmt: &'stmt Statement<'stmt>,
}

impl<'stmt> Row<'stmt> {
    pub fn column_type(&self, index: usize) -> SqlType {
        SqlType::from_code(unsafe { sqlite3_column_type(self.stmt.stmt, index as c_int) })
    }

    pub fn is_null(&self, index: usize) -> bool {
        self.column_type(index) == SqlType::Null
    }

    pub fn get_text(&self, index: usize) -> Result<String> {
        let ty = self.column_type(index);
        if ty != SqlType::Text {
            return Err(SqliteError::InvalidType {
                index,
                sql_type: ty,
            });
        }
        let ptr = unsafe { sqlite3_column_text(self.stmt.stmt, index as c_int) };
        let len = unsafe { sqlite3_column_bytes(self.stmt.stmt, index as c_int) };
        if ptr.is_null() || len <= 0 {
            return Ok(String::new());
        }
        let bytes = unsafe { std::slice::from_raw_parts(ptr, len as usize) };
        String::from_utf8(bytes.to_vec()).map_err(|e| {
            SqliteError::conversion(index, ty, format!("{e}"))
        })
    }

    pub fn get_opt_text(&self, index: usize) -> Result<Option<String>> {
        if self.is_null(index) {
            Ok(None)
        } else {
            Ok(Some(self.get_text(index)?))
        }
    }

    pub fn get_i64(&self, index: usize) -> Result<i64> {
        let ty = self.column_type(index);
        if ty != SqlType::Integer {
            return Err(SqliteError::InvalidType {
                index,
                sql_type: ty,
            });
        }
        Ok(unsafe { sqlite3_column_int64(self.stmt.stmt, index as c_int) })
    }

    pub fn get_i32(&self, index: usize) -> Result<i32> {
        let value = self.get_i64(index)?;
        i32::try_from(value).map_err(|_| SqliteError::IntegralValueOutOfRange { index, value })
    }

    pub fn get_opt_i64(&self, index: usize) -> Result<Option<i64>> {
        if self.is_null(index) {
            Ok(None)
        } else {
            Ok(Some(self.get_i64(index)?))
        }
    }

    pub fn get_f64(&self, index: usize) -> Result<f64> {
        let ty = self.column_type(index);
        match ty {
            SqlType::Real => Ok(unsafe { sqlite3_column_double(self.stmt.stmt, index as c_int) }),
            SqlType::Integer => Ok(self.get_i64(index)? as f64),
            _ => Err(SqliteError::InvalidType {
                index,
                sql_type: ty,
            }),
        }
    }

    pub fn get_opt_f64(&self, index: usize) -> Result<Option<f64>> {
        if self.is_null(index) {
            Ok(None)
        } else {
            Ok(Some(self.get_f64(index)?))
        }
    }
}
RS
