use std::fmt;

use chrono::{Datelike, Local, NaiveDate, NaiveDateTime};
use serde::Serialize;

use crate::blake3;
use crate::sqlite::{Row, SqliteError, SqlType};

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Hash(pub [u8; 32]);

impl Hash {
    pub fn from_hex(s: &str) -> Option<Self> {
        if s.len() != 64 {
            return None;
        }
        let bytes = s.as_bytes();
        let mut out = [0u8; 32];
        for i in 0..32 {
            let hi = hex_val(bytes[i * 2])?;
            let lo = hex_val(bytes[i * 2 + 1])?;
            out[i] = (hi << 4) | lo;
        }
        Some(Hash(out))
    }

    pub fn to_hex(&self) -> String {
        let mut s = String::with_capacity(64);
        for b in self.0 {
            s.push_str(&format!("{:02x}", b));
        }
        s
    }

    pub fn of_basic(question: &str, answer: &str) -> Self {
        let mut data = Vec::with_capacity(5 + question.len() + answer.len());
        data.extend_from_slice(b"Basic");
        data.extend_from_slice(question.as_bytes());
        data.extend_from_slice(answer.as_bytes());
        Hash(blake3::hash(&data))
    }

    pub fn of_cloze_family(text: &str) -> Self {
        let mut data = Vec::with_capacity(5 + text.len());
        data.extend_from_slice(b"Cloze");
        data.extend_from_slice(text.as_bytes());
        Hash(blake3::hash(&data))
    }

    pub fn of_cloze(text: &str, start: usize, end: usize) -> Self {
        let mut data = Vec::with_capacity(5 + text.len() + 16);
        data.extend_from_slice(b"Cloze");
        data.extend_from_slice(text.as_bytes());
        data.extend_from_slice(&(start as u64).to_le_bytes());
        data.extend_from_slice(&(end as u64).to_le_bytes());
        Hash(blake3::hash(&data))
    }
}

fn hex_val(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

impl fmt::Display for Hash {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.to_hex())
    }
}

impl Serialize for Hash {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(&self.to_hex())
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Timestamp(pub NaiveDateTime);

impl Timestamp {
    pub fn now() -> Self {
        Timestamp(Local::now().naive_local())
    }

    pub fn today() -> Date {
        Date(Local::now().naive_local().date())
    }

    pub fn format_db(&self) -> String {
        self.0.format("%Y-%m-%dT%H:%M:%S%.3f").to_string()
    }

    pub fn format_display(&self) -> String {
        self.0.format("%Y-%m-%d %H:%M:%S").to_string()
    }

    pub fn date(&self) -> Date {
        Date(self.0.date())
    }

    pub fn parse_db(s: &str, index: usize, ty: SqlType) -> crate::sqlite::Result<Self> {
        NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S%.3f")
            .or_else(|_| NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S"))
            .map(Timestamp)
            .map_err(|_| {
                SqliteError::conversion(
                    index,
                    ty,
                    format!("Failed to parse timestamp: '{}'.", s),
                )
            })
    }
}

impl Serialize for Timestamp {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(&self.format_db())
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Date(pub NaiveDate);

impl Date {
    pub fn format_db(&self) -> String {
        self.0.format("%Y-%m-%d").to_string()
    }

    pub fn parse_db(s: &str, index: usize, ty: SqlType) -> crate::sqlite::Result<Self> {
        NaiveDate::parse_from_str(s, "%Y-%m-%d")
            .map(Date)
            .map_err(|_| SqliteError::conversion(index, ty, format!("invalid date: {}", s)))
    }

    pub fn add_days(&self, days: i64) -> Self {
        Date(self.0 + chrono::Duration::days(days))
    }

    /// Days from `self` to `other` (other - self).
    pub fn days_until(&self, other: Date) -> i64 {
        (other.0 - self.0).num_days()
    }
}

impl Serialize for Date {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(&self.format_db())
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum Grade {
    Forgot,
    Hard,
    Good,
    Easy,
}

impl Grade {
    pub fn value(&self) -> i64 {
        match self {
            Grade::Forgot => 1,
            Grade::Hard => 2,
            Grade::Good => 3,
            Grade::Easy => 4,
        }
    }

    pub fn is_pass(&self) -> bool {
        matches!(self, Grade::Good | Grade::Easy)
    }

    pub fn db_str(&self) -> &'static str {
        match self {
            Grade::Forgot => "forgot",
            Grade::Hard => "hard",
            Grade::Good => "good",
            Grade::Easy => "easy",
        }
    }

    pub fn parse_db(s: &str, index: usize, ty: SqlType) -> crate::sqlite::Result<Self> {
        match s {
            "forgot" => Ok(Grade::Forgot),
            "hard" => Ok(Grade::Hard),
            "good" => Ok(Grade::Good),
            "easy" => Ok(Grade::Easy),
            // The original message contains this literal placeholder.
            _ => Err(SqliteError::conversion(
                index,
                ty,
                "invalid grade string: {value}".to_string(),
            )),
        }
    }
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Performance {
    pub last_reviewed_at: Timestamp,
    pub stability: f64,
    pub difficulty: f64,
    pub interval_raw: f64,
    pub interval_days: i64,
    pub due_date: Date,
    pub review_count: usize,
}

// ---- Row conversion helpers -------------------------------------------------

pub fn row_hash(row: &Row<'_>, index: usize) -> crate::sqlite::Result<Hash> {
    let ty = row.column_type(index);
    let text = row.get_text(index)?;
    Hash::from_hex(&text).ok_or_else(|| {
        SqliteError::conversion(index, ty, "invalid hash in performance database".to_string())
    })
}

pub fn row_timestamp(row: &Row<'_>, index: usize) -> crate::sqlite::Result<Timestamp> {
    let ty = row.column_type(index);
    let text = row.get_text(index)?;
    Timestamp::parse_db(&text, index, ty)
}

pub fn row_opt_timestamp(row: &Row<'_>, index: usize) -> crate::sqlite::Result<Option<Timestamp>> {
    if row.is_null(index) {
        Ok(None)
    } else {
        Ok(Some(row_timestamp(row, index)?))
    }
}

pub fn row_date(row: &Row<'_>, index: usize) -> crate::sqlite::Result<Date> {
    let ty = row.column_type(index);
    let text = row.get_text(index)?;
    Date::parse_db(&text, index, ty)
}

pub fn row_opt_date(row: &Row<'_>, index: usize) -> crate::sqlite::Result<Option<Date>> {
    if row.is_null(index) {
        Ok(None)
    } else {
        Ok(Some(row_date(row, index)?))
    }
}

pub fn row_grade(row: &Row<'_>, index: usize) -> crate::sqlite::Result<Grade> {
    let ty = row.column_type(index);
    let text = row.get_text(index)?;
    Grade::parse_db(&text, index, ty)
}

pub fn date_today() -> Date {
    Timestamp::today()
}

pub fn naive_date_is_valid(y: i32, m: u32, d: u32) -> bool {
    NaiveDate::from_ymd_opt(y, m, d).is_some()
}

pub fn year_of(date: Date) -> i32 {
    date.0.year()
}
RS
