#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Hash(pub [u8; 32]);

impl Hash {
    pub fn from_hex(s: &str) -> Option<Self> {
        if s.len() != 64 {
            return None;
        }
        let bytes = s.as_bytes();
        let mut out = [0u8; 32];
        for i in 0..32 {
            let hi = hex_val(bytes[i * 2])?;
            let lo = hex_val(bytes[i * 2 + 1])?;
            out[i] = (hi << 4) | lo;
        }
        Some(Hash(out))
    }

    pub fn to_hex(&self) -> String {
        let mut s = String::with_capacity(64);
        for b in self.0 {
            s.push_str(&format!("{:02x}", b));
        }
        s
    }

    pub fn of_basic(question: &str, answer: &str) -> Self {
        let mut data = Vec::with_capacity(5 + question.len() + answer.len());
        data.extend_from_slice(b"Basic");
        data.extend_from_slice(question.as_bytes());
        data.extend_from_slice(answer.as_bytes());
        Hash(blake3::hash(&data))
    }

    pub fn of_cloze_family(text: &str) -> Self {
        let mut data = Vec::with_capacity(5 + text.len());
        data.extend_from_slice(b"Cloze");
        data.extend_from_slice(text.as_bytes());
