{"command":"cat > src/db.rs <<'RS'
use std::collections::BTreeSet;
use std::path::Path;

use serde::Serialize;

use crate::error::{Error, Result};
use crate::sqlite::{Connection, Value};
use crate::types::{
    row_date, row_grade, row_hash, row_opt_date, row_opt_timestamp, row_timestamp, Date, Grade,
    Hash, Performance, Timestamp,
};

const SCHEMA: &str = "

create table cards (
    card_hash text primary key,
    added_at text not null,
    last_reviewed_at text,
    stability real,
    difficulty real,
    interval_raw real,
    interval_days integer,
    due_date text,
    review_count integer not null
) strict;

create table sessions (
    session_id integer primary key,
    started_at text not null,
    ended_at text not null
) strict;

create table reviews (
    review_id integer primary key,
    session_id integer not null
        references sessions (session_id)
        on update cascade
        on delete cascade,
    card_hash text not null
        references cards (card_hash)
        on update cascade
        on delete cascade,
    reviewed_at text not null,
    grade text not null,
    stability real not null,
    difficulty real not null,
    interval_raw real not null,
    interval_days integer not null,
    due_date text not null
) strict;
";

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Review {
    pub review_id: i64,
    pub hash: Hash,
    pub reviewed_at: Timestamp,
    pub grade: Grade,
    pub stability: f64,
    pub difficulty: f64,
    pub interval_raw: f64,
    pub interval_days: i64,
    pub due_date: Date,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Session {
    pub session_id: i64,
    pub started_at: Timestamp,
    pub ended_at: Timestamp,
    pub reviews: Vec<Review>,
}

#[derive(Debug, Clone)]
pub struct SessionReview {
    pub hash: Hash,
    pub reviewed_at: Timestamp,
    pub grade: Grade,
    pub performance: Performance,
}

pub struct Db {
    conn: Connection,
}

impl Db {
    pub fn open(root: &Path) -> Result<Self> {
        let path = root.join("hashcards.db");
        let conn = Connection::open(&path)?;
        let db = Db { conn };
        db.conn.execute("PRAGMA foreign_keys = ON;", &[])?;
        let cards_exists = db
            .conn
            .query_one(
                "select name from sqlite_master where type = 'table' and name = 'cards';",
                &[],
                |row| row.get_text(0),
            )?
            .is_some();
        if !cards_exists {
            db.conn.execute("BEGIN;", &[])?;
            match db.conn.execute_batch(SCHEMA) {
                Ok(()) => {
                    db.conn.execute("COMMIT;", &[])?;
                }
                Err(e) => {
                    let _ = db.conn.execute("ROLLBACK;", &[]);
                    return Err(Error::from(e));
                }
            }
        }
        Ok(db)
    }

    pub fn connection(&self) -> &Connection {
        &self.conn
    }

    pub fn get_all_card_hashes(&self) -> Result<BTreeSet<Hash>> {
        let rows = self
            .conn
            .query_all("select card_hash from cards;", &[], |row| row_hash(row, 0))?;
        Ok(rows.into_iter().collect())
    }

    pub fn get_performance(&self, hash: Hash) -> Result<Option<Performance>> {
        let perf = self.conn.query_one(
            "select last_reviewed_at, stability, difficulty, interval_raw, interval_days, due_date, review_count from cards where card_hash = ?;",
            &[Value::Text(hash.to_hex())],
            |row| {
                let last_reviewed_at = row_opt_timestamp(row, 0)?;
                let stability = row.get_opt_f64(1)?;
                let difficulty = row.get_opt_f64(2)?;
                let interval_raw = row.get_opt_f64(3)?;
                let interval_days = row.get_opt_i64(4)?;
                let due_date = row_opt_date(row, 5)?;
                let review_count = row.get_i32(6)? as usize;
                Ok(match (
                    last_reviewed_at,
                    stability,
                    difficulty,
                    interval_raw,
                    interval_days,
                    due_date,
                ) {
                    (
                        Some(last_reviewed_at),
                        Some(stability),
                        Some(difficulty),
                        Some(interval_raw),
                        Some(interval_days),
                        Some(due_date),
                    ) => Some(Performance {
                        last_reviewed_at,
                        stability,
                        difficulty,
                        interval_raw,
                        interval_days,
                        due_date,
                        review_count,
                    }),
                    _ => None,
                })
            },
        )?;
        Ok(perf.flatten())
    }

    pub fn cards_reviewed_today_count(&self, today: Date) -> Result<i64> {
        Ok(self.conn.query_scalar_i64(
            "select count(*) from reviews where substr(reviewed_at, 1, 10) = ?;",
            &[Value::Text(today.format_db())],
        )?)
    }

    pub fn get_sessions(&self) -> Result<Vec<Session>> {
        let session_rows = self.conn.query_all(
            "select session_id, started_at, ended_at from sessions order by started_at;",
            &[],
            |row| {
                Ok((
                    row.get_i64(0)?,
                    row_timestamp(row, 1)?,
                    row_timestamp(row, 2)?,
                ))
            },
        )?;
        let mut sessions = Vec::new();
        for (session_id, started_at, ended_at) in session_rows {
            let reviews = self.conn.query_all(
                "select review_id, card_hash, reviewed_at, grade, stability, difficulty, interval_raw, interval_days, due_date from reviews where session_id = ? order by reviewed_at;",
                &[Value::Integer(session_id)],
                |row| {
                    Ok(Review {
                        review_id: row.get_i64(0)?,
                        hash: row_hash(row, 1)?,
                        reviewed_at: row_timestamp(row, 2)?,
                        grade: row_grade(row, 3)?,
                        stability: row.get_f64(4)?,
                        difficulty: row.get_f64(5)?,
                        interval_raw: row.get_f64(6)?,
                        interval_days: row.get_i64(7)?,
                        due_date: row_date(row, 8)?,
                    })
                },
            )?;
            sessions.push(Session {
                session_id,
                started_at,
                ended_at,
                reviews,
            });
        }
        Ok(sessions)
    }

    pub fn add_card_if_missing(&self, hash: Hash, added_at: Timestamp) -> Result<()> {
        self.conn.execute(
            "insert or ignore into cards (card_hash, added_at, review_count) values (?, ?, 0);",
            &[
                Value::Text(hash.to_hex()),
                Value::Text(added_at.format_db()),
            ],
        )?;
        Ok(())
    }

    pub fn add_cards_if_missing(&self, hashes: &[Hash], added_at: Timestamp) -> Result<()> {
        self.conn.execute("BEGIN;", &[])?;
        let result = (|| -> Result<()> {
            for hash in hashes {
                self.add_card_if_missing(*hash, added_at)?;
            }
            Ok(())
        })();
        match result {
            Ok(()) => {
                self.conn.execute("COMMIT;", &[])?;
                Ok(())
            }
            Err(e) => {
                let _ = self.conn.execute("ROLLBACK;", &[]);
                Err(e)
            }
        }
    }

    pub fn delete_card(&self, hash: Hash) -> Result<()> {
        self.conn.execute(
            "delete from cards where card_hash = ?;",
            &[Value::Text(hash.to_hex())],
        )?;
        Ok(())
    }

    pub fn save_session(
        &self,
        started_at: Timestamp,
        ended_at: Timestamp,
        reviews: &[SessionReview],
    ) -> Result<()> {
        self.conn.execute("BEGIN;", &[])?;
        let result = (|| -> Result<()> {
            self.conn.execute(
                "insert into sessions (started_at, ended_at) values (?, ?);",
                &[
                    Value::Text(started_at.format_db()),
                    Value::Text(ended_at.format_db()),
                ],
            )?;
            let session_id = self.conn.last_insert_rowid();
            for review in reviews {
                let p = &review.performance;
                self.conn.execute(
                    "insert into reviews (session_id, card_hash, reviewed_at, grade, stability, difficulty, interval_raw, interval_days, due_date) values (?, ?, ?, ?, ?, ?, ?, ?, ?);",
                    &[
                        Value::Integer(session_id),
                        Value::Text(review.hash.to_hex()),
                        Value::Text(review.reviewed_at.format_db()),
                        Value::Text(review.grade.db_str().to_string()),
                        Value::Real(p.stability),
                        Value::Real(p.difficulty),
                        Value::Real(p.interval_raw),
                        Value::Integer(p.interval_days),
                        Value::Text(p.due_date.format_db()),
                    ],
                )?;
                self.conn.execute(
                    "update cards set last_reviewed_at = ?, stability = ?, difficulty = ?, interval_raw = ?, interval_days = ?, due_date = ?, review_count = ? where card_hash = ?;",
                    &[
                        Value::Text(p.last_reviewed_at.format_db()),
                        Value::Real(p.stability),
                        Value::Real(p.difficulty),
                        Value::Real(p.interval_raw),
                        Value::Integer(p.interval_days),
                        Value::Text(p.due_date.format_db()),
                        Value::Integer(p.review_count as i64),
                        Value::Text(review.hash.to_hex()),
                    ],
                )?;
            }
            Ok(())
        })();
        match result {
            Ok(()) => {
                self.conn.execute("COMMIT;", &[])?;
