    difficulty real not null,
    interval_raw real not null,
    interval_days integer not null,
    due_date text not null
) strict;
";

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Review {
    pub review_id: i64,
    pub hash: Hash,
    pub reviewed_at: Timestamp,
    pub grade: Grade,
    pub stability: f64,
    pub difficulty: f64,
    pub interval_raw: f64,
    pub interval_days: i64,
    pub due_date: Date,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Session {
    pub session_id: i64,
    pub started_at: Timestamp,
    pub ended_at: Timestamp,
    pub reviews: Vec<Review>,
}

#[derive(Debug, Clone)]
pub struct SessionReview {
    pub hash: Hash,
    pub reviewed_at: Timestamp,
    pub grade: Grade,
    pub performance: Performance,
}

pub struct Db {
    conn: Connection,
}

impl Db {
    pub fn open(root: &Path) -> Result<Self> {
        let path = root.join("hashcards.db");
        let conn = Connection::open(&path)?;
        let db = Db { conn };
        db.conn.execute("PRAGMA foreign_keys = ON;", &[])?;
        let cards_exists = db
            .conn
            .query_one(
                "select name from sqlite_master where type = 'table' and name = 'cards';",
                &[],
                |row| row.get_text(0),
            )?
            .is_some();
        if !cards_exists {
            db.conn.execute("BEGIN;", &[])?;
            match db.conn.execute_batch(SCHEMA) {
                Ok(()) => {
                    db.conn.execute("COMMIT;", &[])?;
                }
                Err(e) => {
                    let _ = db.conn.execute("ROLLBACK;", &[]);
                    return Err(Error::from(e));
                }
            }
        }
        Ok(db)
    }

    pub fn connection(&self) -> &Connection {
        &self.conn
    }

    pub fn get_all_card_hashes(&self) -> Result<BTreeSet<Hash>> {
        let rows = self
            .conn
            .query_all("select card_hash from cards;", &[], |row| row_hash(row, 0))?;
        Ok(rows.into_iter().collect())
    }

    pub fn get_performance(&self, hash: Hash) -> Result<Option<Performance>> {
        let perf = self.conn.query_one(
            "select last_reviewed_at, stability, difficulty, interval_raw, interval_days, due_date, review_count from cards where card_hash = ?;",
            &[Value::Text(hash.to_hex())],
            |row| {
                let last_reviewed_at = row_opt_timestamp(row, 0)?;
