                    (
                        Some(last_reviewed_at),
                        Some(stability),
                        Some(difficulty),
                        Some(interval_raw),
                        Some(interval_days),
                        Some(due_date),
                    ) => Some(Performance {
                        last_reviewed_at,
                        stability,
                        difficulty,
                        interval_raw,
                        interval_days,
                        due_date,
                        review_count,
                    }),
                    _ => None,
                })
            },
        )?;
        Ok(perf.flatten())
    }

