//! A small CommonMark-flavoured Markdown implementation.
//!
//! It covers the flavour exercised by flashcards: ordinary CommonMark
//! blocks and inlines, tables and TeX math spans, but not strikethrough,
//! task lists, footnotes or other GitHub extensions.  The HTML it emits
//! follows the layout produced by the Markdown renderer used by the
//! reference program.

use std::collections::HashMap;
use std::path::Path;

use crate::entities;

// ---------------------------------------------------------------------------
// Public API

pub struct RenderContext<'a> {
    pub root: &'a Path,
    pub card_file_path: &'a Path,
    pub port: u16,
}

pub fn render_markdown(text: &str, ctx: &RenderContext<'_>) -> String {
    let doc = parse_document(text);
    let mut out = String::new();
    render_blocks(&doc.blocks, &doc, ctx, false, &mut out);
    out
}

pub fn extract_image_destinations(text: &str) -> Vec<String> {
    let doc = parse_document(text);
    let mut out = Vec::new();
    collect_images_blocks(&doc.blocks, &doc, &mut out);
    out
}

// ---------------------------------------------------------------------------
// AST

#[derive(Debug, Clone)]
enum Block {
    Paragraph(String),
    Heading { level: u32, text: String },
    CodeBlock { info: Option<String>, content: String },
    HtmlBlock(String),
    Blockquote(Vec<Block>),
    List(ListData),
    ThematicBreak,
    Table {
        headers: Vec<String>,
        aligns: Vec<Align>,
        rows: Vec<Vec<String>>,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Align {
    None,
    Left,
    Center,
    Right,
}

#[derive(Debug, Clone)]
struct ListData {
    start: Option<u64>, // None: unordered
    loose: bool,
    items: Vec<Vec<Block>>,
}

#[derive(Debug, Clone)]
struct LinkDef {
    dest: String,
    title: Option<String>,
}

struct Document {
    blocks: Vec<Block>,
    refs: HashMap<String, LinkDef>,
}

// ---------------------------------------------------------------------------
// Block parsing

fn parse_document(text: &str) -> Document {
    let lines: Vec<String> = text.lines().map(|s| s.to_string()).collect();
    let mut refs = HashMap::new();
    let blocks = parse_blocks(&lines, &mut refs);
    Document { blocks, refs }
}

fn is_blank(line: &str) -> bool {
    line.chars().all(|c| c == ' ' || c == '\t')
}

/// Column width of the leading indentation and the byte position of the
/// first non-indentation character.  Tabs advance to the next multiple of 4.
fn indent_of(line: &str) -> (usize, usize) {
    let mut col = 0usize;
    let mut pos = 0usize;
    for ch in line.chars() {
        match ch {
            ' ' => {
                col += 1;
                pos += 1;
            }
            '\t' => {
                let advance = 4 - (col % 4);
                col += advance;
                pos += 1;
            }
            _ => break,
        }
    }
    (col, pos)
}

/// Remove up to `max_cols` columns of indentation from a line.
fn strip_indent(line: &str, max_cols: usize) -> String {
    let mut col = 0usize;
    let mut out = String::new();
    let mut iter = line.chars().peekable();
    while col < max_cols {
        match iter.peek() {
            Some(' ') => {
                iter.next();
                col += 1;
            }
            Some('\t') => {
                iter.next();
                let advance = 4 - (col % 4);
                col += advance;
                if col > max_cols {
                    out.push_str(&" ".repeat(col - max_cols));
                }
            }
            _ => break,
        }
    }
    out.extend(iter);
    out
}

/// The line with up to three columns of indentation removed, when it has
/// at most that much.  Returns None for more deeply indented lines.
fn unindented<'a>(line: &'a str) -> Option<String> {
    let (indent, _) = indent_of(line);
    if indent <= 3 {
        Some(strip_indent(line, indent))
    } else {
        None
    }
}

fn parse_atx_heading(line: &str) -> Option<(u32, String)> {
    let s = unindented(line)?;
    let level = s.chars().take_while(|&c| c == '#').count();
    if level == 0 || level > 6 {
        return None;
    }
    let rest = &s[level..];
    if !rest.is_empty() && !rest.starts_with(' ') && !rest.starts_with('\t') {
        return None;
    }
    let mut content = rest.trim().to_string();
    // Optional closing sequence.
    if content.ends_with('#') {
        let trimmed = content.trim_end_matches('#');
        if trimmed.len() < content.len()
            && (trimmed.is_empty() || trimmed.ends_with(' ') || trimmed.ends_with('\t'))
        {
            content = trimmed.trim_end().to_string();
        }
    }
    Some((level as u32, content))
}

fn parse_setext(line: &str) -> Option<u32> {
    let s = unindented(line)?;
    let t = s.trim();
    if !t.is_empty() && t.chars().all(|c| c == '=') {
        Some(1)
    } else if !t.is_empty() && t.chars().all(|c| c == '-') {
        Some(2)
    } else {
        None
    }
}

fn is_thematic_break(line: &str) -> bool {
    let Some(s) = unindented(line) else {
        return false;
    };
    let mut marker: Option<char> = None;
    let mut count = 0usize;
    for ch in s.chars() {
        match ch {
            ' ' | '\t' => {}
            '-' | '*' | '_' => {
                match marker {
                    None => marker = Some(ch),
                    Some(m) if m == ch => {}
                    _ => return false,
                }
                count += 1;
            }
            _ => return false,
        }
    }
    count >= 3
}

struct Fence {
    ch: char,
    len: usize,
    info: String,
    indent: usize,
}

fn parse_fence(line: &str) -> Option<Fence> {
    let (indent, _) = indent_of(line);
    if indent > 3 {
        return None;
    }
    let s = strip_indent(line, indent);
    let first = s.chars().next()?;
    if first != '`' && first != '~' {
        return None;
    }
    let len = s.chars().take_while(|&c| c == first).count();
    if len < 3 {
        return None;
    }
    let info = s[len..].trim().to_string();
    if first == '`' && info.contains('`') {
        return None;
    }
    Some(Fence {
        ch: first,
        len,
        info,
        indent,
    })
}

fn is_fence_close(line: &str, fence: &Fence) -> bool {
    let (indent, _) = indent_of(line);
    if indent > 3 {
        return false;
    }
    let s = strip_indent(line, indent);
    let len = s.chars().take_while(|&c| c == fence.ch).count();
    len >= fence.len && s[len..].trim().is_empty()
}

fn parse_blockquote_prefix(line: &str) -> Option<String> {
    let (indent, _) = indent_of(line);
    if indent > 3 {
        return None;
    }
    let s = strip_indent(line, indent);
    if let Some(rest) = s.strip_prefix('>') {
        if let Some(r) = rest.strip_prefix(' ') {
            Some(r.to_string())
        } else if let Some(r) = rest.strip_prefix('\t') {
            // A tab after > counts as one space of the (up to) content
            // indentation in a simplified form.
            Some(format!("   {}", r))
        } else {
            Some(rest.to_string())
        }
    } else {
        None
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ListKind {
    Bullet(char),
    Ordered(char, u64), // delimiter, number
}

#[derive(Debug, Clone)]
struct ListMarker {
    kind: ListKind,
    indent: usize,
    content_col: usize, // columns from line start to content
}

fn parse_list_marker(line: &str) -> Option<ListMarker> {
    let (indent, _) = indent_of(line);
    if indent > 3 {
        return None;
    }
    let s = strip_indent(line, indent);
    let bytes = s.as_bytes();
    if bytes.is_empty() {
        return None;
    }
    let (kind, marker_len) = match bytes[0] {
        b'-' | b'+' | b'*' => (ListKind::Bullet(bytes[0] as char), 1usize),
        b'0'..=b'9' => {
            let mut i = 0;
            while i < bytes.len() && bytes[i].is_ascii_digit() && i < 9 {
                i += 1;
            }
            if i == 0 || i >= bytes.len() || (bytes[i] != b'.' && bytes[i] != b')') {
                return None;
            }
            let num: u64 = s[..i].parse().ok()?;
            (ListKind::Ordered(bytes[i] as char, num), i + 1)
        }
        _ => return None,
    };
    let after = &s[marker_len..];
    if after.is_empty() {
        return Some(ListMarker {
            kind,
            indent,
            content_col: indent + marker_len + 1,
        });
    }
    if !after.starts_with(' ') && !after.starts_with('\t') {
        return None;
    }
    // Columns of whitespace after the marker.
    let mut spaces = 0usize;
    let mut col_pos = indent + marker_len;
    for ch in after.chars() {
        match ch {
            ' ' => {
                spaces += 1;
                col_pos += 1;
            }
            '\t' => {
                let advance = 4 - (col_pos % 4);
                spaces += advance;
                col_pos += advance;
            }
            _ => break,
        }
    }
    let content_col = if spaces >= 5 || after.trim().is_empty() {
        indent + marker_len + 1
    } else {
        col_pos
    };
    Some(ListMarker {
        kind,
        indent,
        content_col,
    })
}

fn list_kinds_compatible(a: ListKind, b: ListKind) -> bool {
    match (a, b) {
        (ListKind::Bullet(x), ListKind::Bullet(y)) => x == y,
        (ListKind::Ordered(x, _), ListKind::Ordered(y, _)) => x == y,
        _ => false,
    }
}

fn split_table_row(line: &str) -> Vec<String> {
    let t = line.trim();
    let mut cells: Vec<String> = Vec::new();
    let mut current = String::new();
    let mut chars = t.chars().peekable();
    let mut in_code = false;
    while let Some(ch) = chars.next() {
        match ch {
            '\\' => {
                current.push('\\');
                if let Some(&next) = chars.peek() {
                    chars.next();
                    current.push(next);
                }
            }
            '`' => {
                in_code = !in_code;
                current.push('`');
            }
            '|' if !in_code => {
                cells.push(current.trim().to_string());
                current = String::new();
            }
            _ => current.push(ch),
        }
    }
    cells.push(current.trim().to_string());
    if t.starts_with('|') && !cells.is_empty() && cells[0].is_empty() {
        cells.remove(0);
    }
    if t.ends_with('|') && !t.ends_with("\\|") && !cells.is_empty() && cells[cells.len() - 1].is_empty() {
        cells.pop();
    }
    cells
}

fn parse_table_delimiter(line: &str) -> Option<Vec<Align>> {
    let cells = split_table_row(line);
    if cells.is_empty() {
        return None;
    }
    let mut aligns = Vec::new();
    for cell in &cells {
        let c = cell.trim();
        let left = c.starts_with(':');
        let right = c.ends_with(':');
        let core = c.trim_matches(':');
        if core.is_empty() || !core.chars().all(|ch| ch == '-') {
            return None;
        }
        aligns.push(match (left, right) {
            (true, true) => Align::Center,
            (true, false) => Align::Left,
            (false, true) => Align::Right,
            (false, false) => Align::None,
        });
    }
    Some(aligns)
}

fn html_block_start(line: &str) -> Option<HtmlBlockKind> {
    let s = unindented(line)?;
    let t = s.as_str();
    if !t.starts_with('<') {
        return None;
    }
    let lower = t.to_ascii_lowercase();
    for tag in ["script", "pre", "style", "textarea"] {
        let open = format!("<{}", tag);
        if lower.starts_with(&open) {
            let after = &lower[open.len()..];
            if after.is_empty()
                || after.starts_with(' ')
                || after.starts_with('\t')
                || after.starts_with('>')
                || after.starts_with("/>")
            {
                return Some(HtmlBlockKind::UntilClose(tag.to_string()));
            }
        }
    }
    if t.starts_with("<!--") {
        return Some(HtmlBlockKind::UntilText("-->".to_string()));
    }
    if t.starts_with("<?") {
        return Some(HtmlBlockKind::UntilText("?>".to_string()));
    }
    if t.starts_with("<![CDATA[") {
        return Some(HtmlBlockKind::UntilText("]]>".to_string()));
    }
    if t.starts_with("<!") && t[2..].chars().next().is_some_and(|c| c.is_ascii_uppercase()) {
        return Some(HtmlBlockKind::UntilText(">".to_string()));
    }
    // A block-level tag or any complete tag begins an HTML block that runs
    // until a blank line.
    if parse_inline_html_tag(t).is_some() {
        return Some(HtmlBlockKind::UntilBlank);
    }
    None
}

#[derive(Debug)]
enum HtmlBlockKind {
    UntilClose(String),
    UntilText(String),
    UntilBlank,
}

fn is_paragraph_interrupt(line: &str, para_lines: &[String]) -> bool {
    if parse_fence(line).is_some() || parse_atx_heading(line).is_some() {
        return true;
    }
    if parse_blockquote_prefix(line).is_some() || is_thematic_break(line) {
        return true;
    }
    if html_block_start(line).is_some() {
        return true;
    }
    if let Some(marker) = parse_list_marker(line) {
        // Lists interrupt a paragraph only when they are not empty, and an
        // ordered list must start at 1.
        let content = strip_indent(line, marker.content_col.min(indent_of(line).0 + 10));
        let _ = content;
        let after_nonempty = {
            let (_, pos) = indent_of(line);
            line[pos..].trim().len() > 1
        };
        match marker.kind {
            ListKind::Bullet(_) => return after_nonempty,
            ListKind::Ordered(_, n) => return after_nonempty && n == 1,
        }
    }
    let _ = para_lines;
    false
}

fn parse_blocks(lines: &[String], refs: &mut HashMap<String, LinkDef>) -> Vec<Block> {
    let mut blocks: Vec<Block> = Vec::new();
    let mut i = 0usize;
    while i < lines.len() {
        let line = &lines[i];
        if is_blank(line) {
            i += 1;
            continue;
        }

        // Fenced code block.
        if let Some(fence) = parse_fence(line) {
            i += 1;
            let mut content_lines: Vec<String> = Vec::new();
            while i < lines.len() && !is_fence_close(&lines[i], &fence) {
                content_lines.push(strip_indent(&lines[i], fence.indent));
                i += 1;
            }
            if i < lines.len() {
                i += 1; // closing fence
            }
            let mut content = content_lines.join("\n");
            if !content_lines.is_empty() {
                content.push('\n');
            }
            let info = fence
                .info
                .split_whitespace()
                .next()
                .filter(|s| !s.is_empty())
                .map(|s| s.to_string());
            blocks.push(Block::CodeBlock { info, content });
            continue;
        }

        // ATX heading.
        if let Some((level, text)) = parse_atx_heading(line) {
            blocks.push(Block::Heading { level, text });
            i += 1;
            continue;
        }

        // HTML block.
        if let Some(kind) = html_block_start(line) {
            let mut html_lines: Vec<String> = Vec::new();
            let mut closed = false;
            while i < lines.len() {
                let l = &lines[i];
                match &kind {
                    HtmlBlockKind::UntilBlank => {
                        if is_blank(l) {
                            break;
                        }
                        html_lines.push(l.clone());
                        i += 1;
                    }
                    HtmlBlockKind::UntilText(end) => {
                        html_lines.push(l.clone());
                        i += 1;
                        if l.contains(end.as_str()) {
                            closed = true;
                            break;
                        }
                    }
                    HtmlBlockKind::UntilClose(tag) => {
                        html_lines.push(l.clone());
                        i += 1;
                        if l.to_ascii_lowercase().contains(&format!("</{}", tag)) {
                            closed = true;
                            break;
                        }
                    }
                }
            }
            let _ = closed;
            blocks.push(Block::HtmlBlock(html_lines.join("\n")));
            continue;
        }

        // Blockquote.
        if parse_blockquote_prefix(line).is_some() {
            let mut inner: Vec<String> = Vec::new();
            while i < lines.len() {
                let l = &lines[i];
                if let Some(stripped) = parse_blockquote_prefix(l) {
                    inner.push(stripped);
                    i += 1;
                } else if !is_blank(l)
                    && !inner.is_empty()
                    && !is_blank(inner.last().unwrap())
                    && !is_paragraph_interrupt(l, &inner)
                {
                    // Lazy continuation.
                    inner.push(l.clone());
                    i += 1;
                } else {
                    break;
                }
            }
            let inner_blocks = parse_blocks(&inner, refs);
            blocks.push(Block::Blockquote(inner_blocks));
            continue;
        }

        // Thematic break.
        if is_thematic_break(line) {
            blocks.push(Block::ThematicBreak);
            i += 1;
            continue;
        }

        // List.
        if parse_list_marker(line).is_some() {
            let list = parse_list(lines, &mut i, refs);
            blocks.push(Block::List(list));
            continue;
        }

        // Indented code block.
        if indent_of(line).0 >= 4 {
            let mut code_lines: Vec<String> = Vec::new();
            while i < lines.len() {
                let l = &lines[i];
                if indent_of(l).0 >= 4 {
                    code_lines.push(strip_indent(l, 4));
                    i += 1;
                } else if is_blank(l) {
                    // Tentatively include; trailing blanks are trimmed.
                    code_lines.push(String::new());
                    i += 1;
                } else {
                    break;
                }
            }
            while code_lines.last().is_some_and(|l| l.is_empty()) {
                code_lines.pop();
            }
            blocks.push(Block::CodeBlock {
                info: None,
                content: code_lines.join("\n"),
            });
            continue;
        }

        // Paragraph, with setext/table handling.
        let mut para: Vec<String> = vec![line.clone()];
        i += 1;
        let mut setext_level: Option<u32> = None;
        let mut table: Option<(Vec<String>, Vec<Align>)> = None;
        while i < lines.len() {
            let l = &lines[i];
            if is_blank(l) {
                break;
            }
            if para.len() == 1 {
                if let Some(level) = parse_setext(l) {
                    setext_level = Some(level);
                    i += 1;
                    break;
                }
                if para[0].contains('|') {
                    if let Some(aligns) = parse_table_delimiter(l) {
                        let headers = split_table_row(&para[0]);
                        if headers.len() == aligns.len() && !headers.is_empty() {
                            table = Some((headers, aligns));
                            i += 1;
                            break;
                        }
                    }
                }
            }
            if is_paragraph_interrupt(l, &para) {
                break;
            }
            para.push(l.clone());
            i += 1;
        }
        if let Some(level) = setext_level {
            blocks.push(Block::Heading {
                level,
                text: para.join("\n").trim().to_string(),
            });
            continue;
        }
        if let Some((headers, aligns)) = table {
            let mut rows: Vec<Vec<String>> = Vec::new();
            while i < lines.len() && !is_blank(&lines[i]) {
                // A line that starts another block ends the table.
                if parse_fence(&lines[i]).is_some()
                    || parse_atx_heading(&lines[i]).is_some()
                    || parse_blockquote_prefix(&lines[i]).is_some()
                {
                    break;
                }
                let mut cells = split_table_row(&lines[i]);
                cells.resize(headers.len(), String::new());
                cells.truncate(headers.len());
                rows.push(cells);
                i += 1;
            }
            blocks.push(Block::Table {
                headers,
                aligns,
                rows,
            });
            continue;
        }
        let text = para.join("\n");
        if let Some(remaining) = strip_link_refs(&text, refs) {
            if !remaining.trim().is_empty() {
                blocks.push(Block::Paragraph(remaining));
            }
        }
    }
    blocks
}

fn parse_list(
    lines: &[String],
    i: &mut usize,
    refs: &mut HashMap<String, LinkDef>,
) -> ListData {
    let first = parse_list_marker(&lines[*i]).unwrap();
    let first_kind = first.kind;
    let start = match first_kind {
        ListKind::Bullet(_) => None,
        ListKind::Ordered(_, n) => Some(n),
    };
    let mut items: Vec<Vec<Block>> = Vec::new();
    let mut loose = false;

    while *i < lines.len() {
        let Some(marker) = parse_list_marker(&lines[*i]) else {
            break;
        };
        if !list_kinds_compatible(first_kind, marker.kind) || marker.indent > 3 {
            break;
        }
        let content_col = marker.content_col;
        let first_content = strip_indent(&lines[*i], content_col);
        let mut item_lines: Vec<String> = vec![first_content];
        *i += 1;
        let mut item_done = false;
        while *i < lines.len() && !item_done {
            let l = &lines[*i];
            if is_blank(l) {
                // Consume a run of blank lines and decide what they end.
                let mut j = *i;
                while j < lines.len() && is_blank(&lines[j]) {
                    j += 1;
                }
                if j >= lines.len() {
                    *i = j;
                    item_done = true;
                    break;
                }
                let next = &lines[j];
                if indent_of(next).0 >= content_col {
                    for _ in *i..j {
                        item_lines.push(String::new());
                    }
                    *i = j;
                    continue;
                }
                if let Some(next_marker) = parse_list_marker(next) {
                    if list_kinds_compatible(first_kind, next_marker.kind) {
                        loose = true;
                    }
                    *i = j;
                    item_done = true;
                    break;
                }
                // Blank line followed by unindented non-item text ends
                // this list item (and the list).
                *i = j;
                item_done = true;
                break;
            }
            if indent_of(l).0 >= content_col {
                item_lines.push(strip_indent(l, content_col));
                *i += 1;
                continue;
            }
            if let Some(m) = parse_list_marker(l) {
                if list_kinds_compatible(first_kind, m.kind) {
                    item_done = true;
                    break;
                } else {
                    // A different list at the same level ends this one.
                    item_done = true;
                    break;
                }
            }
            if parse_atx_heading(l).is_some()
                || parse_fence(l).is_some()
                || is_thematic_break(l)
            {
                item_done = true;
                break;
            }
            // Lazy continuation of the item's paragraph.
            item_lines.push(l.clone());
            *i += 1;
        }
        // A blank line inside the item followed by more content makes the
        // whole list loose.
        let mut seen_blank = false;
        for l in &item_lines {
            if is_blank(l) {
                seen_blank = true;
            } else if seen_blank {
                loose = true;
            }
        }
        let item_blocks = parse_blocks(&item_lines, refs);
        items.push(item_blocks);
        // Continue with the next item if one follows.
        match lines.get(*i).and_then(|l| parse_list_marker(l)) {
            Some(m) if list_kinds_compatible(first_kind, m.kind) => continue,
            _ => break,
        }
    }

    ListData {
        start,
        loose,
        items,
    }
}

// ---------------------------------------------------------------------------
// Link reference definitions

fn normalize_label(label: &str) -> String {
    let decoded = decode_text_entities(label);
    let mut out = String::new();
    let mut last_space = true; // also trims the start
    for ch in decoded.chars() {
        if ch.is_whitespace() {
            if !last_space {
                out.push(' ');
                last_space = true;
            }
        } else {
            for lc in ch.to_lowercase() {
                out.push(lc);
            }
            last_space = false;
        }
    }
    while out.ends_with(' ') {
        out.pop();
    }
    out
}

fn strip_link_refs(text: &str, refs: &mut HashMap<String, LinkDef>) -> Option<String> {
    let mut rest = text;
    loop {
        let parsed = parse_link_ref_at(rest);
        match parsed {
            Some((label, dest, title, consumed)) => {
                let key = normalize_label(&label);
                refs.entry(key).or_insert(LinkDef { dest, title });
                rest = &rest[consumed..];
                // Skip a single following newline.
                if let Some(r) = rest.strip_prefix('\n') {
                    rest = r;
                }
                if rest.trim().is_empty() {
                    return None;
                }
            }
            None => return Some(rest.to_string()),
        }
    }
}

/// Parse a link reference definition at the start of `s`.
/// Returns (label, destination, title, bytes consumed including the
/// trailing newline-free remainder handling done by the caller).
fn parse_link_ref_at(s: &str) -> Option<(String, String, Option<String>, usize)> {
    let bytes = s.as_bytes();
    let mut pos = 0usize;
    // Up to three spaces of indentation.
    let mut spaces = 0;
    while pos < bytes.len() && bytes[pos] == b' ' && spaces < 4 {
        pos += 1;
        spaces += 1;
    }
    if spaces > 3 || pos >= bytes.len() || bytes[pos] != b'[' {
        return None;
    }
    let label_end = find_label_end(s, pos)?;
    let label = &s[pos + 1..label_end];
    if label.is_empty() || label.len() > 999 {
        return None;
    }
    let mut p = label_end + 1;
    if p >= bytes.len() || bytes[p] != b':' {
        return None;
    }
    p += 1;
    p = skip_spaces_and_one_newline(s, p);
    let (dest, p2) = parse_destination_at(s, p)?;
    p = p2;
    // Optional title, which must be separated by whitespace.
    let after_ws = skip_spaces_and_one_newline(s, p);
    let mut title = None;
    if after_ws > p || p >= bytes.len() {
        if let Some((t, p3)) = parse_title_at(s, after_ws) {
            title = Some(t);
            p = p3;
        }
    }
    // Only spaces/tabs may follow until the end of the line.
    let mut q = p;
    while q < bytes.len() && (bytes[q] == b' ' || bytes[q] == b'\t') {
        q += 1;
    }
    if q < bytes.len() && bytes[q] != b'\n' {
        return None;
    }
    Some((label.to_string(), dest, title, q))
}

fn skip_inline_spaces(s: &str, mut pos: usize) -> usize {
    let bytes = s.as_bytes();
    while pos < bytes.len() && (bytes[pos] == b' ' || bytes[pos] == b'\t' || bytes[pos] == b'\n') {
        pos += 1;
    }
    pos
}

fn skip_spaces_and_one_newline(s: &str, mut pos: usize) -> usize {
    let bytes = s.as_bytes();
    let mut seen_newline = false;
    while pos < bytes.len() {
        match bytes[pos] {
            b' ' | b'\t' => pos += 1,
            b'\n' if !seen_newline => {
                seen_newline = true;
                pos += 1;
            }
            _ => break,
        }
    }
    pos
}

/// Find the `]` matching the `[` at byte position `start` in `s`.
fn find_label_end(s: &str, start: usize) -> Option<usize> {
    let bytes = s.as_bytes();
    let mut depth = 0usize;
    let mut i = start;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' if i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() => {
                i += 2;
            }
            b'`' => {
                // Skip a code span if it closes.
                let run = count_run(s, i, '`');
                if let Some(end) = find_code_close(s, i + run, run) {
                    i = end;
                } else {
                    i += run;
                }
            }
            b'[' => {
                depth += 1;
                i += 1;
            }
            b']' => {
                depth -= 1;
                if depth == 0 {
                    return Some(i);
                }
                i += 1;
            }
            _ => {
                i += s[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
            }
        }
    }
    None
}

fn count_run(s: &str, start: usize, ch: char) -> usize {
    s[start..].chars().take_while(|&c| c == ch).count()
}

/// Find the byte position just past a closing code-span run of length `run`.
fn find_code_close(s: &str, from: usize, run: usize) -> Option<usize> {
    let bytes = s.as_bytes();
    let mut i = from;
    while i < bytes.len() {
        if bytes[i] == b'`' {
            let r = count_run(s, i, '`');
            if r == run {
                return Some(i + r);
            }
            i += r;
        } else {
            i += 1;
        }
    }
    None
}

/// Parse a link destination at `pos` (angle-bracketed or bare).
fn parse_destination_at(s: &str, pos: usize) -> Option<(String, usize)> {
    let bytes = s.as_bytes();
    if pos >= bytes.len() {
        return None;
    }
    if bytes[pos] == b'<' {
        let mut i = pos + 1;
        while i < bytes.len() {
            match bytes[i] {
                b'\\' if i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() => {
                    i += 2;
                }
                b'>' => {
                    let raw = &s[pos + 1..i];
                    return Some((decode_destination(raw), i + 1));
                }
                b'\n' | b'<' => return None,
                _ => i += s[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1),
            }
        }
        None
    } else {
        let mut i = pos;
        let mut depth: i32 = 0;
        while i < bytes.len() {
            let b = bytes[i];
            if b == b'\\' && i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() {
                i += 2;
                continue;
            }
            if b == b' ' || b == b'\t' || b == b'\n' || (b as char).is_control() {
                break;
            }
            match b {
                b'(' => {
                    depth += 1;
                    if depth > 32 {
                        return None;
                    }
                }
                b')' => {
                    if depth == 0 {
                        break;
                    }
                    depth -= 1;
                }
                b'<' => return None,
                _ => {}
            }
            i += s[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
        }
        if i == pos {
            return None;
        }
        Some((decode_destination(&s[pos..i]), i))
    }
}

/// Parse a link title at `pos`.
fn parse_title_at(s: &str, pos: usize) -> Option<(String, usize)> {
    let bytes = s.as_bytes();
    if pos >= bytes.len() {
        return None;
    }
    let (open, close) = match bytes[pos] {
        b'"' => (b'"', b'"'),
        b'\'' => (b'\'', b'\''),
        b'(' => (b'(', b')'),
        _ => return None,
    };
    let _ = open;
    let mut i = pos + 1;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' if i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() => {
                i += 2;
            }
            b if b == close => {
                if close == b')' && bytes[pos] == b'(' && s[pos + 1..i].contains('(') {
                    // Unescaped '(' is not allowed inside a parenthesised title.
                    // (A \\( sequence would have been skipped above.)
                    let inner = &s[pos + 1..i];
                    if inner.contains('(') {
                        return None;
                    }
                }
                let raw = &s[pos + 1..i];
                return Some((decode_text_entities(raw), i + 1));
            }
            b'(' if close == b')' => return None,
            _ => i += s[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1),
        }
    }
    None
}

// ---------------------------------------------------------------------------
// Decoding helpers (entities, escapes, percent decoding)

fn parse_entity(s: &str) -> Option<(String, usize)> {
    // s starts with '&'.
    let rest = &s[1..];
    if let Some(num) = rest.strip_prefix('#') {
        let (digits, radix, prefix_len) = if let Some(hex) = num
            .strip_prefix('x')
            .or_else(|| num.strip_prefix('X'))
        {
            (hex, 16u32, 2usize)
        } else {
            (num, 10u32, 1usize)
        };
        let digit_len = digits
            .chars()
            .take_while(|c| c.is_digit(radix))
            .map(|c| c.len_utf8())
            .sum::<usize>();
        if digit_len == 0 {
            return None;
        }
        let after = &digits[digit_len..];
        if !after.starts_with(';') {
            return None;
        }
        let value = u32::from_str_radix(&digits[..digit_len], radix).unwrap_or(0x110000);
        let ch = if value == 0 || value > 0x10ffff || (0xd800..=0xdfff).contains(&value) {
            '\u{fffd}'
        } else {
            char::from_u32(value).unwrap_or('\u{fffd}')
        };
        return Some((ch.to_string(), 1 + prefix_len + digit_len + 1));
    }
    // Named entity: longest run of alphanumerics ending in ';'.
    let name_len = rest
        .chars()
        .take_while(|c| c.is_ascii_alphanumeric())
        .map(|c| c.len_utf8())
        .sum::<usize>();
    if name_len == 0 || !rest[name_len..].starts_with(';') {
        return None;
    }
    let name = &rest[..name_len];
    entities::lookup(name).map(|v| (v.to_string(), 1 + name_len + 1))
}

/// Resolve backslash escapes and entities (but not percent sequences).
fn decode_text_entities(s: &str) -> String {
    let mut out = String::new();
    let mut i = 0usize;
    let bytes = s.as_bytes();
    while i < bytes.len() {
        let ch = s[i..].chars().next().unwrap();
        match ch {
            '\\' if i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() => {
                out.push(bytes[i + 1] as char);
                i += 2;
            }
            '&' => {
                if let Some((decoded, len)) = parse_entity(&s[i..]) {
                    out.push_str(&decoded);
                    i += len;
                } else {
                    out.push('&');
                    i += 1;
                }
            }
            _ => {
                out.push(ch);
                i += ch.len_utf8();
            }
        }
    }
    out
}

/// Resolve backslash escapes, entities and percent sequences, interpreting
/// the result as (lossy) UTF-8.
fn decode_destination(raw: &str) -> String {
    let mut bytes: Vec<u8> = Vec::new();
    let mut i = 0usize;
    let b = raw.as_bytes();
    while i < b.len() {
        let ch = raw[i..].chars().next().unwrap();
        match ch {
            '\\' if i + 1 < b.len() && b[i + 1].is_ascii_punctuation() => {
                bytes.push(b[i + 1]);
                i += 2;
            }
            '%' if i + 2 < b.len()
                && (b[i + 1] as char).is_ascii_hexdigit()
                && (b[i + 2] as char).is_ascii_hexdigit() =>
            {
                let v = u8::from_str_radix(&raw[i + 1..i + 3], 16).unwrap_or(b'%');
                bytes.push(v);
                i += 3;
            }
            '&' => {
                if let Some((decoded, len)) = parse_entity(&raw[i..]) {
                    bytes.extend_from_slice(decoded.as_bytes());
                    i += len;
                } else {
                    bytes.push(b'&');
                    i += 1;
                }
            }
            _ => {
                let mut buf = [0u8; 4];
                bytes.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                i += ch.len_utf8();
            }
        }
    }
    String::from_utf8_lossy(&bytes).into_owned()
}
