        let mut i = pos + 2;
        while i + 1 < bytes.len() {
            if bytes[i] == b'$' && bytes[i + 1] == b'$' && !is_escaped(i) {
                let content = s[pos + 2..i].to_string();
                return Some((
                    i + 2 - pos,
                    Inline::Math {
                        content,
                        display: true,
                    },
                ));
            }
            i += 1;
        }
        return None;
    }
    // Inline math.
    let next = s[pos + 1..].chars().next()?;
    if next.is_whitespace() {
        return None;
    }
    let mut i = pos + 1;
    while i < bytes.len() {
        if bytes[i] == b'$' && !is_escaped(i) {
            let prev = s[..i].chars().next_back().unwrap();
            if prev.is_whitespace() {
                return None;
            }
            let content = s[pos + 1..i].to_string();
            if content.is_empty() {
                return None;
            }
            return Some((
                i + 1 - pos,
                Inline::Math {
                    content,
                    display: false,
                },
            ));
        }
        i += 1;
    }
    None
}

fn parse_inlines(text: &str, refs: &HashMap<String, LinkDef>, in_link: bool) -> Vec<Inline> {
    let mut nodes: Vec<Inline> = Vec::new();
    let bytes = text.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        let ch = text[i..].chars().next().unwrap();
        match ch {
            '\n' => {
                let hard = match nodes.last_mut() {
                    Some(Inline::Text(t)) if t.ends_with("  ") => {
                        while t.ends_with(' ') {
                            t.pop();
                        }
                        true
                    }
                    _ => false,
                };
                // A text node emptied by trimming should be dropped.
                if let Some(Inline::Text(t)) = nodes.last() {
                    if t.is_empty() {
                        nodes.pop();
                    }
                }
                nodes.push(if hard { Inline::HardBreak } else { Inline::SoftBreak });
                i += 1;
            }
            '\\' => {
                let next = text[i + 1..].chars().next();
                match next {
                    Some('\n') => {
                        nodes.push(Inline::HardBreak);
                        i += 2;
                    }
                    Some(c) if c.is_ascii_punctuation() => {
                        push_text(&mut nodes, &c.to_string());
                        i += 1 + c.len_utf8();
                    }
                    _ => {
                        push_text(&mut nodes, "\\");
                        i += 1;
                    }
                }
            }
            '`' => {
                let run = count_run(text, i, '`');
                if let Some(end) = find_code_close(text, i + run, run) {
                    let raw = &text[i + run..end - run];
                    let mut content: String = raw.chars().map(|c| if c == '\n' { ' ' } else { c }).collect();
                    if content.len() >= 2
                        && content.starts_with(' ')
                        && content.ends_with(' ')
                        && content.trim().len() > 0
                    {
                        content.remove(0);
                        content.pop();
                    }
                    nodes.push(Inline::Code(content));
                    i = end;
                } else {
                    push_text(&mut nodes, &"`".repeat(run));
                    i += run;
                }
            }
            '&' => {
                if let Some((decoded, len)) = parse_entity(&text[i..]) {
                    push_text(&mut nodes, &decoded);
                    i += len;
                } else {
                    push_text(&mut nodes, "&");
                    i += 1;
                }
            }
            '<' => match parse_angle(text, i) {
                Some((raw, end, Some(dest))) => {
                    // Autolink.
                    if in_link {
                        push_text(&mut nodes, "<");
                        i += 1;
                    } else {
                        nodes.push(Inline::Link {
                            dest,
                            title: None,
                            children: vec![Inline::Text(raw)],
                        });
                        i = end;
                    }
                }
                Some((raw, end, None)) => {
                    nodes.push(Inline::RawHtml(raw));
                    i = end;
                }
                None => {
                    push_text(&mut nodes, "<");
                    i += 1;
                }
            },
            '!' if bytes.get(i + 1) == Some(&b'[') => {
                match try_parse_link(text, i + 1, refs) {
                    Some((end, label, dest, title)) => {
                        let alt = parse_inlines(&label, refs, false);
                        nodes.push(Inline::Image { dest, title, alt });
                        i = end;
                    }
                    None => {
                        push_text(&mut nodes, "!");
                        i += 1;
                    }
                }
            }
            '[' if !in_link => match try_parse_link(text, i, refs) {
                Some((end, label, dest, title)) => {
                    let children = parse_inlines(&label, refs, true);
                    nodes.push(Inline::Link {
                        dest,
                        title,
                        children,
                    });
                    i = end;
                }
                None => {
                    push_text(&mut nodes, "[");
                    i += 1;
                }
            },
            '$' => match try_parse_math(text, i) {
                Some((consumed, node)) => {
                    nodes.push(node);
                    i += consumed;
                }
                None => {
                    push_text(&mut nodes, "$");
                    i += 1;
                }
            },
            '*' | '_' => {
                let run = count_run(text, i, ch);
                let (can_open, can_close) = delimiter_flanking(text, i, i + run, ch);
                nodes.push(Inline::Delimiter {
                    ch,
                    len: run,
                    can_open,
                    can_close,
                });
                i += run;
            }
            _ => {
                let start = i;
                while i < bytes.len() {
                    let c = text[i..].chars().next().unwrap();
                    if matches!(c, '\n' | '\\' | '`' | '&' | '<' | '[' | '$' | '*' | '_')
                        || (c == '!' && bytes.get(i + 1) == Some(&b'['))
                    {
                        break;
                    }
                    i += c.len_utf8();
                }
                push_text(&mut nodes, &text[start..i]);
            }
        }
    }
    process_emphasis(nodes)
}

fn process_emphasis(mut nodes: Vec<Inline>) -> Vec<Inline> {
    let mut i = 0usize;
    while i < nodes.len() {
        let (ch, len, can_open, can_close) = match &nodes[i] {
            Inline::Delimiter {
                ch,
                len,
                can_open,
                can_close,
            } => (*ch, *len, *can_open, *can_close),
            _ => {
                i += 1;
                continue;
            }
        };
        if !can_close || len == 0 {
            i += 1;
            continue;
        }
        // Find the nearest earlier opener for the same character.
        let mut opener: Option<usize> = None;
        for j in (0..i).rev() {
            if let Inline::Delimiter {
                ch: och,
                len: olen,
                can_open: oopen,
                can_close: oclose,
            } = &nodes[j]
            {
                if *och != ch || !oopen || *olen == 0 {
                    continue;
                }
                let odd = (can_open || *oclose)
                    && (olen + len) % 3 == 0
                    && !(olen % 3 == 0 && len % 3 == 0);
                if odd {
                    continue;
                }
                opener = Some(j);
                break;
            }
        }
        let Some(j) = opener else {
            i += 1;
            continue;
        };
        let olen = match &nodes[j] {
            Inline::Delimiter { len, .. } => *len,
            _ => unreachable!(),
        };
        let use_count = if olen >= 2 && len >= 2 { 2 } else { 1 };
        if let Inline::Delimiter { len: l, .. } = &mut nodes[j] {
            *l -= use_count;
        }
        if let Inline::Delimiter { len: l, .. } = &mut nodes[i] {
            *l -= use_count;
        }
        let children: Vec<Inline> = nodes.drain(j + 1..i).collect();
        let wrapped = if use_count == 2 {
            Inline::Strong(children)
        } else {
            Inline::Emphasis(children)
        };
        nodes.insert(j + 1, wrapped);
        // The closer is now at j+2 (after opener and wrapped node).
        i = j + 2;
    }
    // Turn leftover delimiters into text.
    let mut out: Vec<Inline> = Vec::new();
    for node in nodes {
        match node {
            Inline::Delimiter { ch, len, .. } => {
                if len > 0 {
                    push_text(&mut out, &ch.to_string().repeat(len));
                }
            }
            other => out.push(other),
        }
    }
    out
}

// ---------------------------------------------------------------------------
// Rendering

fn escape_text(s: &str, out: &mut String) {
    for ch in s.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(ch),
        }
    }
}

fn escape_attr(s: &str, out: &mut String) {
    for ch in s.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(ch),
        }
    }
}

fn escape_href(s: &str, out: &mut String) {
    for byte in s.bytes() {
        match byte {
            b'&' => out.push_str("&amp;"),
            b'\'' => out.push_str("&#x27;"),
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' => out.push(byte as char),
            b'!' | b'#' | b'$' | b'%' | b'(' | b')' | b'*' | b'+' | b',' | b'-' | b'.'
            | b'/' | b':' | b';' | b'=' | b'?' | b'@' | b'^' | b'_' | b'~' => {
                out.push(byte as char)
            }
            _ => {
                out.push_str(&format!("%{:02X}", byte));
            }
        }
    }
}

/// Resolve a Markdown image destination to the URL the web server serves it
/// from.
fn image_url(dest: &str, ctx: &RenderContext<'_>) -> String {
    if let Some(rel) = dest.strip_prefix("@/") {
        format!("http://localhost:{}/file/{}", ctx.port, rel)
    } else {
        let card_abs = std::fs::canonicalize(ctx.card_file_path)
            .unwrap_or_else(|_| ctx.card_file_path.to_path_buf());
        let dir = card_abs.parent().map(|p| p.to_path_buf()).unwrap_or_default();
        let joined = dir.join(dest);
        let canon = std::fs::canonicalize(&joined).unwrap_or(joined);
        let rel = canon
            .strip_prefix(ctx.root)
            .map(|p| p.to_path_buf())
            .unwrap_or(canon);
        format!(
            "http://localhost:{}/file/{}",
            ctx.port,
            rel.to_string_lossy()
        )
    }
}

fn is_audio_dest(dest: &str) -> bool {
    Path::new(dest)
        .extension()
        .is_some_and(|e| e == "mp3" || e == "wav" || e == "ogg")
}

fn render_inlines(
    nodes: &[Inline],
    doc: &Document,
    ctx: &RenderContext<'_>,
    out: &mut String,
) {
    for node in nodes {
        render_inline(node, doc, ctx, out);
    }
}

fn render_inline(node: &Inline, doc: &Document, ctx: &RenderContext<'_>, out: &mut String) {
    match node {
        Inline::Text(text) => escape_text(text, out),
        Inline::Code(code) => {
            out.push_str("<code>");
            escape_text(code, out);
            out.push_str("</code>");
        }
        Inline::Math { content, display } => {
            if *display {
                out.push_str("<span class=\"math math-display\">");
            } else {
                out.push_str("<span class=\"math math-inline\">");
            }
            escape_attr(content, out);
            out.push_str("</span>");
        }
        Inline::Emphasis(children) => {
            out.push_str("<em>");
            render_inlines(children, doc, ctx, out);
            out.push_str("</em>");
        }
        Inline::Strong(children) => {
            out.push_str("<strong>");
            render_inlines(children, doc, ctx, out);
            out.push_str("</strong>");
        }
        Inline::Link {
            dest,
            title,
            children,
        } => {
            out.push_str("<a href=\"");
            escape_href(dest, out);
            out.push('"');
            if let Some(title) = title {
                if !title.is_empty() {
                    out.push_str(" title=\"");
                    escape_attr(title, out);
                    out.push('"');
                }
            }
            out.push('>');
            render_inlines(children, doc, ctx, out);
            out.push_str("</a>");
        }
        Inline::Image { dest, title, alt } => {
            let url = image_url(dest, ctx);
            if is_audio_dest(dest) {
                out.push_str("<audio controls src=\"");
                out.push_str(&url);
                out.push_str("\" title=\"");
                if let Some(title) = title {
                    out.push_str(title);
                }
                out.push_str("\"></audio>");
                // The reference renderer emits the image description as
                // ordinary inline content after an audio element.
                render_inlines(alt, doc, ctx, out);
            } else {
                out.push_str("<img src=\"");
                escape_href(&url, out);
                out.push_str("\" alt=\"");
                let mut alt_text = String::new();
                collect_alt_text(alt, &mut alt_text);
                escape_attr(&alt_text, out);
                out.push('"');
                if let Some(title) = title {
                    if !title.is_empty() {
                        out.push_str(" title=\"");
                        escape_attr(title, out);
                        out.push('"');
                    }
                }
                out.push_str(" />");
            }
        }
        Inline::RawHtml(html) => out.push_str(html),
        Inline::SoftBreak => out.push('\n'),
        Inline::HardBreak => out.push_str("<br />\n"),
        Inline::Delimiter { ch, len, .. } => {
            for _ in 0..*len {
                out.push(*ch);
            }
        }
    }
}

fn collect_alt_text(nodes: &[Inline], out: &mut String) {
    for node in nodes {
        match node {
            Inline::Text(t) | Inline::Code(t) => out.push_str(t),
            Inline::Math { content, .. } => out.push_str(content),
            Inline::Emphasis(c) | Inline::Strong(c) => collect_alt_text(c, out),
            Inline::Link { children, .. } => collect_alt_text(children, out),
            Inline::Image { alt, .. } => collect_alt_text(alt, out),
            Inline::SoftBreak | Inline::HardBreak => out.push(' '),
            Inline::RawHtml(_) => {}
            Inline::Delimiter { ch, len, .. } => {
                for _ in 0..*len {
                    out.push(*ch);
                }
            }
        }
    }
}

fn render_blocks(
    blocks: &[Block],
    doc: &Document,
    ctx: &RenderContext<'_>,
    tight: bool,
    out: &mut String,
) {
    for block in blocks {
        render_block(block, doc, ctx, tight, out);
    }
}

fn render_block(
    block: &Block,
    doc: &Document,
    ctx: &RenderContext<'_>,
    tight: bool,
    out: &mut String,
) {
    match block {
        Block::Paragraph(text) => {
            let inlines = parse_inlines(text, &doc.refs, false);
            if tight {
                render_inlines(&inlines, doc, ctx, out);
            } else {
                out.push_str("<p>");
                render_inlines(&inlines, doc, ctx, out);
                out.push_str("</p>\n");
            }
        }
        Block::Heading { level, text } => {
            let inlines = parse_inlines(text, &doc.refs, false);
            out.push_str(&format!("<h{}>", level));
            render_inlines(&inlines, doc, ctx, out);
            out.push_str(&format!("</h{}>\n", level));
        }
        Block::CodeBlock { info, content } => {
            out.push_str("<pre><code");
            if let Some(info) = info {
                out.push_str(" class=\"language-");
                escape_attr(info, out);
                out.push('"');
            }
            out.push('>');
            escape_text(content, out);
            out.push_str("</code></pre>\n");
        }
        Block::HtmlBlock(html) => {
            out.push_str(html);
            out.push('\n');
        }
        Block::Blockquote(inner) => {
            out.push_str("<blockquote>\n");
            render_blocks(inner, doc, ctx, false, out);
            out.push_str("</blockquote>\n");
        }
        Block::ThematicBreak => out.push_str("<hr />\n"),
        Block::List(list) => render_list(list, doc, ctx, out),
        Block::Table {
            headers,
            aligns,
            rows,
        } => {
            out.push_str("<table><thead><tr>");
            for (idx, header) in headers.iter().enumerate() {
                out.push_str("<th");
                push_align(aligns[idx], out);
                out.push('>');
                let inlines = parse_inlines(header, &doc.refs, false);
                render_inlines(&inlines, doc, ctx, out);
                out.push_str("</th>");
            }
            out.push_str("</tr></thead><tbody>\n");
            for row in rows {
                out.push_str("<tr>");
                for (idx, cell) in row.iter().enumerate() {
                    out.push_str("<td");
                    push_align(aligns[idx], out);
                    out.push('>');
                    let inlines = parse_inlines(cell, &doc.refs, false);
                    render_inlines(&inlines, doc, ctx, out);
                    out.push_str("</td>");
                }
                out.push_str("</tr>\n");
            }
            out.push_str("</tbody></table>\n");
        }
    }
}

fn push_align(align: Align, out: &mut String) {
    match align {
        Align::None => {}
        Align::Left => out.push_str(" style=\"text-align: left\""),
        Align::Center => out.push_str(" style=\"text-align: center\""),
        Align::Right => out.push_str(" style=\"text-align: right\""),
    }
}

fn render_list(list: &ListData, doc: &Document, ctx: &RenderContext<'_>, out: &mut String) {
    match list.start {
        None => out.push_str("<ul>\n"),
        Some(1) => out.push_str("<ol>\n"),
        Some(n) => out.push_str(&format!("<ol start=\"{}\">\n", n)),
    }
    for item in &list.items {
        if item.is_empty() {
            out.push_str("<li></li>\n");
            continue;
        }
        if list.loose {
            out.push_str("<li>\n");
            render_blocks(item, doc, ctx, false, out);
            out.push_str("</li>\n");
        } else {
            out.push_str("<li>");
            // Tight lists suppress paragraph tags; a paragraph that is
            // followed by another block still contributes its trailing
            // newline.
            for (idx, block) in item.iter().enumerate() {
                let is_para = matches!(block, Block::Paragraph(_));
                render_block(block, doc, ctx, true, out);
                if is_para && idx + 1 < item.len() {
                    out.push('\n');
                }
            }
            out.push_str("</li>\n");
        }
    }
    match list.start {
        None => out.push_str("</ul>\n"),
        Some(_) => out.push_str("</ol>\n"),
    }
}

// ---------------------------------------------------------------------------
// Image extraction (for media validation)

fn collect_images_blocks(blocks: &[Block], doc: &Document, out: &mut Vec<String>) {
    for block in blocks {
        match block {
            Block::Paragraph(text) | Block::Heading { text, .. } => {
                let inlines = parse_inlines(text, &doc.refs, false);
                collect_images_inlines(&inlines, out);
            }
            Block::Blockquote(inner) => collect_images_blocks(inner, doc, out),
            Block::List(list) => {
                for item in &list.items {
                    collect_images_blocks(item, doc, out);
                }
            }
            Block::Table { headers, rows, .. } => {
                for cell in headers.iter().chain(rows.iter().flatten()) {
                    let inlines = parse_inlines(cell, &doc.refs, false);
                    collect_images_inlines(&inlines, out);
                }
            }
            _ => {}
        }
    }
}

fn collect_images_inlines(nodes: &[Inline], out: &mut Vec<String>) {
    for node in nodes {
        match node {
            Inline::Image { dest, alt, .. } => {
                out.push(dest.clone());
                collect_images_inlines(alt, out);
            }
            Inline::Link { children, .. } => collect_images_inlines(children, out),
            Inline::Emphasis(c) | Inline::Strong(c) => collect_images_inlines(c, out),
            _ => {}
        }
    }
}
RS
"}

actions.command:
cat >> src/markdown.rs <<'RS'

// ---------------------------------------------------------------------------
// Inline parsing

#[derive(Debug, Clone)]
enum Inline {
    Text(String),
    Code(String),
    Math { content: String, display: bool },
    Emphasis(Vec<Inline>),
    Strong(Vec<Inline>),
    Link {
        dest: String,
        title: Option<String>,
        children: Vec<Inline>,
    },
    Image {
        dest: String,
        title: Option<String>,
        alt: Vec<Inline>,
    },
    RawHtml(String),
    SoftBreak,
    HardBreak,
    Delimiter {
        ch: char,
        len: usize,
        can_open: bool,
        can_close: bool,
    },
}

fn push_text(nodes: &mut Vec<Inline>, text: &str) {
    if text.is_empty() {
        return;
    }
    if let Some(Inline::Text(prev)) = nodes.last_mut() {
        prev.push_str(text);
    } else {
        nodes.push(Inline::Text(text.to_string()));
    }
}

fn is_unicode_punctuation(ch: char) -> bool {
    // std has no Unicode punctuation test; this approximation covers the
    // ASCII range exactly and treats other non-alphanumeric, non-space
    // characters as punctuation, which matches in almost all real text.
    if ch.is_ascii() {
        ch.is_ascii_punctuation()
    } else {
        !ch.is_alphanumeric() && !ch.is_whitespace()
    }
}

fn delimiter_flanking(s: &str, start: usize, end: usize, ch: char) -> (bool, bool) {
    let before = s[..start].chars().next_back();
    let after = s[end..].chars().next();
    let before_ws = before.is_none_or(|c| c.is_whitespace());
    let after_ws = after.is_none_or(|c| c.is_whitespace());
    let before_punct = before.is_some_and(is_unicode_punctuation);
    let after_punct = after.is_some_and(is_unicode_punctuation);
    let left_flanking = !after_ws && (!after_punct || before_ws || before_punct);
    let right_flanking = !before_ws && (!before_punct || after_ws || after_punct);
    if ch == '*' {
        (left_flanking, right_flanking)
    } else {
        (
            left_flanking && (!right_flanking || before_punct),
            right_flanking && (!left_flanking || after_punct),
        )
    }
}

/// Try to parse a link (or, with is_image, its label) whose `[` is at `pos`.
/// Returns (end position, label text, destination, title).
fn try_parse_link(
    s: &str,
    pos: usize,
    refs: &HashMap<String, LinkDef>,
) -> Option<(usize, String, String, Option<String>)> {
    let label_end = find_label_end(s, pos)?;
    let label = s[pos + 1..label_end].to_string();
    let after = label_end + 1;
    let bytes = s.as_bytes();

    // Inline destination.
    if after < bytes.len() && bytes[after] == b'(' {
        if let Some((dest, title, end)) = parse_inline_destination(s, after) {
            return Some((end, label, dest, title));
        }
    }

    // Full or collapsed reference.
    let mut p = after;
    // Allow whitespace (including one newline) before a reference label.
    let saved = p;
    p = skip_spaces_and_one_newline(s, p);
    if p < bytes.len() && bytes[p] == b'[' {
        if let Some(second_end) = find_label_end(s, p) {
            let second = &s[p + 1..second_end];
            let key = if second.is_empty() {
                normalize_label(&label)
            } else {
                normalize_label(second)
            };
            if let Some(def) = refs.get(&key) {
                return Some((second_end + 1, label, def.dest.clone(), def.title.clone()));
            }
        }
    } else {
        p = saved;
    }

    // Shortcut reference.
    let key = normalize_label(&label);
    if let Some(def) = refs.get(&key) {
        return Some((after, label, def.dest.clone(), def.title.clone()));
    }
    let _ = p;
    None
}

/// Parse `(destination "title")` starting at the `(`.
fn parse_inline_destination(s: &str, pos: usize) -> Option<(String, Option<String>, usize)> {
    let bytes = s.as_bytes();
    let mut p = skip_inline_spaces(s, pos + 1);
    if p < bytes.len() && bytes[p] == b')' {
        return Some((String::new(), None, p + 1));
    }
    let (dest, p2) = parse_destination_at(s, p)?;
    p = p2;
    let after_ws = skip_inline_spaces(s, p);
    let had_ws = after_ws > p;
    p = after_ws;
    let mut title = None;
    if p < bytes.len() && bytes[p] != b')' {
        if !had_ws {
            return None;
        }
        let (t, p3) = parse_title_at(s, p)?;
        title = Some(t);
        p = skip_inline_spaces(s, p3);
    }
    if p < bytes.len() && bytes[p] == b')' {
        Some((dest, title, p + 1))
    } else {
        None
    }
}

/// Parse an autolink or inline HTML tag at a `<`.  For autolinks the second
/// return value is Some(destination); for raw HTML it is None.
fn parse_angle(s: &str, pos: usize) -> Option<(String, usize, Option<String>)> {
    let rest = &s[pos..];
    // Comments, processing instructions, declarations, CDATA.
    for (prefix, terminator) in [
        ("<!--", "-->"),
        ("<?", "?>"),
        ("<![CDATA[", "]]>"),
    ] {
        if rest.starts_with(prefix) {
            if let Some(idx) = rest[prefix.len()..].find(terminator) {
                let total = prefix.len() + idx + terminator.len();
                return Some((rest[..total].to_string(), pos + total, None));
            } else {
                return None;
            }
        }
    }
    if rest.starts_with("<!")
        && rest[2..]
            .chars()
            .next()
            .is_some_and(|c| c.is_ascii_uppercase())
    {
        if let Some(idx) = rest.find('>') {
            return Some((rest[..=idx].to_string(), pos + idx + 1, None));
        }
        return None;
    }

    // Autolink: <scheme:...> or <email>.
    if let Some(gt) = rest.find('>') {
        let inner = &rest[1..gt];
        if !inner.is_empty()
            && !inner.chars().any(|c| c == ' ' || c == '<' || (c as u32) < 0x20)
        {
            if is_autolink_uri(inner) {
                return Some((inner.to_string(), pos + gt + 1, Some(inner.to_string())));
            }
            if is_autolink_email(inner) {
                return Some((
                    inner.to_string(),
                    pos + gt + 1,
                    Some(format!("mailto:{}", inner)),
                ));
            }
        }
    }

    // Ordinary tag.
    let end = parse_inline_html_tag(rest)?;
    Some((rest[..end].to_string(), pos + end, None))
}

fn is_autolink_uri(s: &str) -> bool {
    let Some(colon) = s.find(':') else {
        return false;
    };
    let scheme = &s[..colon];
    if scheme.len() < 2 || scheme.len() > 32 {
        return false;
    }
    let mut chars = scheme.chars();
    if !chars.next().is_some_and(|c| c.is_ascii_alphabetic()) {
        return false;
    }
    scheme
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || matches!(c, '+' | '-' | '.'))
}

fn is_autolink_email(s: &str) -> bool {
    let Some(at) = s.find('@') else {
        return false;
    };
    let (local, domain) = (&s[..at], &s[at + 1..]);
    if local.is_empty()
        || !local
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '!' | '#' | '$' | '%' | '&' | '\'' | '*' | '+' | '/' | '=' | '?' | '^' | '_' | '`' | '{' | '|' | '}' | '~' | '-'))
    {
        return false;
    }
    if domain.is_empty() {
        return false;
    }
    let segments: Vec<&str> = domain.split('.').collect();
    if segments.len() < 2 {
        return false;
    }
    segments.iter().all(|seg| {
        !seg.is_empty()
            && seg.len() <= 63
            && !seg.starts_with('-')
            && !seg.ends_with('-')
            && seg.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
    })
}

/// Parse an HTML tag at the start of `s`; returns the length consumed.
fn parse_inline_html_tag(s: &str) -> Option<usize> {
    let bytes = s.as_bytes();
    if bytes.first() != Some(&b'<') {
        return None;
    }
    let mut i = 1usize;
    let closing = if bytes.get(i) == Some(&b'/') {
        i += 1;
        true
    } else {
        false
    };
    // Tag name.
    if i >= bytes.len() || !bytes[i].is_ascii_alphabetic() {
        return None;
    }
    while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'-') {
        i += 1;
    }
    if closing {
        while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t' || bytes[i] == b'\n') {
            i += 1;
        }
        if i < bytes.len() && bytes[i] == b'>' {
            return Some(i + 1);
        }
        return None;
    }
    // Attributes.
    loop {
        let ws_start = i;
        while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t' || bytes[i] == b'\n') {
            i += 1;
        }
        if i >= bytes.len() {
            return None;
        }
        if bytes[i] == b'>' {
            return Some(i + 1);
        }
        if bytes[i] == b'/' && bytes.get(i + 1) == Some(&b'>') {
            return Some(i + 2);
        }
        if i == ws_start {
            return None; // attributes must be preceded by whitespace
        }
        // Attribute name.
        if !(bytes[i].is_ascii_alphabetic() || bytes[i] == b'_' || bytes[i] == b':') {
            return None;
        }
        i += 1;
        while i < bytes.len()
            && (bytes[i].is_ascii_alphanumeric() || matches!(bytes[i], b'_' | b'.' | b':' | b'-'))
        {
            i += 1;
        }
        // Optional value.
        let mut j = i;
        while j < bytes.len() && (bytes[j] == b' ' || bytes[j] == b'\t' || bytes[j] == b'\n') {
            j += 1;
        }
        if j < bytes.len() && bytes[j] == b'=' {
            j += 1;
            while j < bytes.len() && (bytes[j] == b' ' || bytes[j] == b'\t' || bytes[j] == b'\n') {
                j += 1;
            }
            if j >= bytes.len() {
                return None;
            }
            match bytes[j] {
                b'"' | b'\'' => {
                    let quote = bytes[j];
                    j += 1;
                    while j < bytes.len() && bytes[j] != quote {
                        j += 1;
                    }
                    if j >= bytes.len() {
                        return None;
                    }
                    j += 1;
                }
                _ => {
                    let start = j;
                    while j < bytes.len()
                        && !matches!(bytes[j], b' ' | b'\t' | b'\n' | b'"' | b'\'' | b'=' | b'<' | b'>' | b'`')
                    {
                        j += 1;
                    }
                    if j == start {
                        return None;
                    }
                }
            }
            i = j;
        }
    }
}

/// Find the end of a math span starting at `pos` (a `$`).
/// Returns (bytes consumed for the whole span, the node) if the `$` opens
/// math, or None to treat it as a literal.
fn try_parse_math(s: &str, pos: usize) -> Option<(usize, Inline)> {
    let bytes = s.as_bytes();
    debug_assert_eq!(bytes[pos], b'$');
    let is_escaped = |idx: usize| {
        let mut backslashes = 0usize;
        let mut k = idx;
        while k > 0 && bytes[k - 1] == b'\\' {
            backslashes += 1;
            k -= 1;
        }
        backslashes % 2 == 1
    };
    if bytes.get(pos + 1) == Some(&b'$') {
        // Display math.
        let mut i = pos + 2;
        while i + 1 < bytes.len() {
            if bytes[i] == b'$' && bytes[i + 1] == b'$' && !is_escaped(i) {
                let content = s[pos + 2..i].to_string();
                return Some((
                    i + 2 - pos,
                    Inline::Math {
                        content,
                        display: true,
                    },
                ));
            }
            i += 1;
        }
        return None;
    }
    // Inline math.
    let next = s[pos + 1..].chars().next()?;
    if next.is_whitespace() {
        return None;
    }
    let mut i = pos + 1;
    while i < bytes.len() {
        if bytes[i] == b'$' && !is_escaped(i) {
            let prev = s[..i].chars().next_back().unwrap();
            if prev.is_whitespace() {
                return None;
            }
            let content = s[pos + 1..i].to_string();
            if content.is_empty() {
                return None;
            }
            return Some((
                i + 1 - pos,
                Inline::Math {
                    content,
                    display: false,
                },
            ));
        }
        i += 1;
    }
    None
}

fn parse_inlines(text: &str, refs: &HashMap<String, LinkDef>, in_link: bool) -> Vec<Inline> {
    let mut nodes: Vec<Inline> = Vec::new();
    let bytes = text.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        let ch = text[i..].chars().next().unwrap();
        match ch {
            '\n' => {
                let hard = match nodes.last_mut() {
                    Some(Inline::Text(t)) if t.ends_with("  ") => {
                        while t.ends_with(' ') {
                            t.pop();
                        }
                        true
                    }
                    _ => false,
                };
                // A text node emptied by trimming should be dropped.
                if let Some(Inline::Text(t)) = nodes.last() {
                    if t.is_empty() {
                        nodes.pop();
                    }
                }
                nodes.push(if hard { Inline::HardBreak } else { Inline::SoftBreak });
                i += 1;
            }
            '\\' => {
                let next = text[i + 1..].chars().next();
                match next {
                    Some('\n') => {
                        nodes.push(Inline::HardBreak);
                        i += 2;
                    }
                    Some(c) if c.is_ascii_punctuation() => {
                        push_text(&mut nodes, &c.to_string());
                        i += 1 + c.len_utf8();
                    }
                    _ => {
                        push_text(&mut nodes, "\\");
                        i += 1;
                    }
                }
            }
            '`' => {
                let run = count_run(text, i, '`');
                if let Some(end) = find_code_close(text, i + run, run) {
                    let raw = &text[i + run..end - run];
                    let mut content: String = raw.chars().map(|c| if c == '\n' { ' ' } else { c }).collect();
                    if content.len() >= 2
                        && content.starts_with(' ')
                        && content.ends_with(' ')
                        && content.trim().len() > 0
                    {
                        content.remove(0);
                        content.pop();
                    }
                    nodes.push(Inline::Code(content));
                    i = end;
                } else {
                    push_text(&mut nodes, &"`".repeat(run));
                    i += run;
                }
            }
            '&' => {
                if let Some((decoded, len)) = parse_entity(&text[i..]) {
                    push_text(&mut nodes, &decoded);
                    i += len;
                } else {
                    push_text(&mut nodes, "&");
                    i += 1;
                }
            }
            '<' => match parse_angle(text, i) {
                Some((raw, end, Some(dest))) => {
                    // Autolink.
                    if in_link {
                        push_text(&mut nodes, "<");
                        i += 1;
                    } else {
                        nodes.push(Inline::Link {
                            dest,
                            title: None,
                            children: vec![Inline::Text(raw)],
                        });
                        i = end;
                    }
                }
                Some((raw, end, None)) => {
                    nodes.push(Inline::RawHtml(raw));
                    i = end;
                }
                None => {
                    push_text(&mut nodes, "<");
                    i += 1;
                }
            },
            '!' if bytes.get(i + 1) == Some(&b'[') => {
                match try_parse_link(text, i + 1, refs) {
                    Some((end, label, dest, title)) => {
                        let alt = parse_inlines(&label, refs, false);
                        nodes.push(Inline::Image { dest, title, alt });
                        i = end;
                    }
                    None => {
                        push_text(&mut nodes, "!");
                        i += 1;
                    }
                }
            }
            '[' if !in_link => match try_parse_link(text, i, refs) {
                Some((end, label, dest, title)) => {
                    let children = parse_inlines(&label, refs, true);
                    nodes.push(Inline::Link {
                        dest,
                        title,
                        children,
                    });
                    i = end;
                }
                None => {
                    push_text(&mut nodes, "[");
                    i += 1;
                }
            },
            '$' => match try_parse_math(text, i) {
                Some((consumed, node)) => {
                    nodes.push(node);
                    i += consumed;
                }
                None => {
                    push_text(&mut nodes, "$");
                    i += 1;
                }
            },
            '*' | '_' => {
                let run = count_run(text, i, ch);
                let (can_open, can_close) = delimiter_flanking(text, i, i + run, ch);
                nodes.push(Inline::Delimiter {
                    ch,
                    len: run,
                    can_open,
                    can_close,
                });
                i += run;
            }
            _ => {
                let start = i;
                while i < bytes.len() {
                    let c = text[i..].chars().next().unwrap();
                    if matches!(c, '\n' | '\\' | '`' | '&' | '<' | '[' | '$' | '*' | '_')
                        || (c == '!' && bytes.get(i + 1) == Some(&b'['))
                    {
                        break;
                    }
                    i += c.len_utf8();
                }
                push_text(&mut nodes, &text[start..i]);
            }
        }
    }
    process_emphasis(nodes)
}

fn process_emphasis(mut nodes: Vec<Inline>) -> Vec<Inline> {
    let mut i = 0usize;
    while i < nodes.len() {
        let (ch, len, can_open, can_close) = match &nodes[i] {
            Inline::Delimiter {
                ch,
                len,
                can_open,
                can_close,
            } => (*ch, *len, *can_open, *can_close),
            _ => {
                i += 1;
                continue;
            }
        };
        if !can_close || len == 0 {
            i += 1;
            continue;
        }
        // Find the nearest earlier opener for the same character.
        let mut opener: Option<usize> = None;
        for j in (0..i).rev() {
            if let Inline::Delimiter {
                ch: och,
                len: olen,
                can_open: oopen,
                can_close: oclose,
            } = &nodes[j]
            {
                if *och != ch || !oopen || *olen == 0 {
                    continue;
                }
                let odd = (can_open || *oclose)
                    && (olen + len) % 3 == 0
                    && !(olen % 3 == 0 && len % 3 == 0);
                if odd {
                    continue;
                }
                opener = Some(j);
                break;
            }
        }
        let Some(j) = opener else {
            i += 1;
            continue;
        };
        let olen = match &nodes[j] {
            Inline::Delimiter { len, .. } => *len,
            _ => unreachable!(),
        };
        let use_count = if olen >= 2 && len >= 2 { 2 } else { 1 };
        if let Inline::Delimiter { len: l, .. } = &mut nodes[j] {
            *l -= use_count;
        }
        if let Inline::Delimiter { len: l, .. } = &mut nodes[i] {
            *l -= use_count;
        }
        let children: Vec<Inline> = nodes.drain(j + 1..i).collect();
        let wrapped = if use_count == 2 {
            Inline::Strong(children)
        } else {
            Inline::Emphasis(children)
        };
        nodes.insert(j + 1, wrapped);
        // The closer is now at j+2 (after opener and wrapped node).
        i = j + 2;
    }
    // Turn leftover delimiters into text.
    let mut out: Vec<Inline> = Vec::new();
    for node in nodes {
        match node {
            Inline::Delimiter { ch, len, .. } => {
                if len > 0 {
                    push_text(&mut out, &ch.to_string().repeat(len));
                }
            }
            other => out.push(other),
        }
    }
    out
}

// ---------------------------------------------------------------------------
// Rendering

fn escape_text(s: &str, out: &mut String) {
    for ch in s.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(ch),
        }
    }
}

fn escape_attr(s: &str, out: &mut String) {
    for ch in s.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(ch),
        }
    }
}

fn escape_href(s: &str, out: &mut String) {
    for byte in s.bytes() {
        match byte {
            b'&' => out.push_str("&amp;"),
            b'\'' => out.push_str("&#x27;"),
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' => out.push(byte as char),
            b'!' | b'#' | b'$' | b'%' | b'(' | b')' | b'*' | b'+' | b',' | b'-' | b'.'
            | b'/' | b':' | b';' | b'=' | b'?' | b'@' | b'^' | b'_' | b'~' => {
                out.push(byte as char)
            }
            _ => {
                out.push_str(&format!("%{:02X}", byte));
            }
        }
    }
}

/// Resolve a Markdown image destination to the URL the web server serves it
/// from.
fn image_url(dest: &str, ctx: &RenderContext<'_>) -> String {
    if let Some(rel) = dest.strip_prefix("@/") {
        format!("http://localhost:{}/file/{}", ctx.port, rel)
    } else {
        let card_abs = std::fs::canonicalize(ctx.card_file_path)
            .unwrap_or_else(|_| ctx.card_file_path.to_path_buf());
        let dir = card_abs.parent().map(|p| p.to_path_buf()).unwrap_or_default();
        let joined = dir.join(dest);
        let canon = std::fs::canonicalize(&joined).unwrap_or(joined);
        let rel = canon
            .strip_prefix(ctx.root)
            .map(|p| p.to_path_buf())
            .unwrap_or(canon);
        format!(
            "http://localhost:{}/file/{}",
            ctx.port,
            rel.to_string_lossy()
        )
    }
}

fn is_audio_dest(dest: &str) -> bool {
    Path::new(dest)
        .extension()
        .is_some_and(|e| e == "mp3" || e == "wav" || e == "ogg")
}

fn render_inlines(
    nodes: &[Inline],
    doc: &Document,
    ctx: &RenderContext<'_>,
    out: &mut String,
) {
    for node in nodes {
        render_inline(node, doc, ctx, out);
    }
}

fn render_inline(node: &Inline, doc: &Document, ctx: &RenderContext<'_>, out: &mut String) {
    match node {
        Inline::Text(text) => escape_text(text, out),
        Inline::Code(code) => {
            out.push_str("<code>");
            escape_text(code, out);
            out.push_str("</code>");
        }
        Inline::Math { content, display } => {
            if *display {
                out.push_str("<span class=\"math math-display\">");
            } else {
                out.push_str("<span class=\"math math-inline\">");
            }
            escape_attr(content, out);
            out.push_str("</span>");
        }
        Inline::Emphasis(children) => {
            out.push_str("<em>");
            render_inlines(children, doc, ctx, out);
            out.push_str("</em>");
        }
        Inline::Strong(children) => {
            out.push_str("<strong>");
            render_inlines(children, doc, ctx, out);
            out.push_str("</strong>");
        }
        Inline::Link {
            dest,
            title,
            children,
        } => {
            out.push_str("<a href=\"");
            escape_href(dest, out);
            out.push('"');
            if let Some(title) = title {
                if !title.is_empty() {
                    out.push_str(" title=\"");
                    escape_attr(title, out);
                    out.push('"');
                }
            }
            out.push('>');
            render_inlines(children, doc, ctx, out);
            out.push_str("</a>");
        }
        Inline::Image { dest, title, alt } => {
            let url = image_url(dest, ctx);
            if is_audio_dest(dest) {
                out.push_str("<audio controls src=\"");
                out.push_str(&url);
                out.push_str("\" title=\"");
                if let Some(title) = title {
                    out.push_str(title);
                }
                out.push_str("\"></audio>");
                // The reference renderer emits the image description as
                // ordinary inline content after an audio element.
                render_inlines(alt, doc, ctx, out);
            } else {
                out.push_str("<img src=\"");
                escape_href(&url, out);
                out.push_str("\" alt=\"");
                let mut alt_text = String::new();
                collect_alt_text(alt, &mut alt_text);
                escape_attr(&alt_text, out);
                out.push('"');
                if let Some(title) = title {
                    if !title.is_empty() {
                        out.push_str(" title=\"");
                        escape_attr(title, out);
                        out.push('"');
                    }
                }
                out.push_str(" />");
            }
        }
        Inline::RawHtml(html) => out.push_str(html),
        Inline::SoftBreak => out.push('\n'),
        Inline::HardBreak => out.push_str("<br />\n"),
        Inline::Delimiter { ch, len, .. } => {
            for _ in 0..*len {
                out.push(*ch);
            }
        }
    }
}

fn collect_alt_text(nodes: &[Inline], out: &mut String) {
    for node in nodes {
        match node {
            Inline::Text(t) | Inline::Code(t) => out.push_str(t),
            Inline::Math { content, .. } => out.push_str(content),
            Inline::Emphasis(c) | Inline::Strong(c) => collect_alt_text(c, out),
            Inline::Link { children, .. } => collect_alt_text(children, out),
            Inline::Image { alt, .. } => collect_alt_text(alt, out),
            Inline::SoftBreak | Inline::HardBreak => out.push(' '),
            Inline::RawHtml(_) => {}
            Inline::Delimiter { ch, len, .. } => {
                for _ in 0..*len {
                    out.push(*ch);
                }
            }
        }
    }
}

fn render_blocks(
    blocks: &[Block],
    doc: &Document,
    ctx: &RenderContext<'_>,
    tight: bool,
    out: &mut String,
) {
    for block in blocks {
        render_block(block, doc, ctx, tight, out);
    }
}

fn render_block(
    block: &Block,
    doc: &Document,
    ctx: &RenderContext<'_>,
    tight: bool,
    out: &mut String,
) {
    match block {
        Block::Paragraph(text) => {
            let inlines = parse_inlines(text, &doc.refs, false);
            if tight {
                render_inlines(&inlines, doc, ctx, out);
            } else {
                out.push_str("<p>");
                render_inlines(&inlines, doc, ctx, out);
                out.push_str("</p>\n");
            }
        }
        Block::Heading { level, text } => {
            let inlines = parse_inlines(text, &doc.refs, false);
            out.push_str(&format!("<h{}>", level));
            render_inlines(&inlines, doc, ctx, out);
            out.push_str(&format!("</h{}>\n", level));
        }
        Block::CodeBlock { info, content } => {
            out.push_str("<pre><code");
            if let Some(info) = info {
                out.push_str(" class=\"language-");
                escape_attr(info, out);
                out.push('"');
            }
            out.push('>');
            escape_text(content, out);
            out.push_str("</code></pre>\n");
        }
        Block::HtmlBlock(html) => {
            out.push_str(html);
            out.push('\n');
        }
        Block::Blockquote(inner) => {
            out.push_str("<blockquote>\n");
            render_blocks(inner, doc, ctx, false, out);
            out.push_str("</blockquote>\n");
        }
        Block::ThematicBreak => out.push_str("<hr />\n"),
        Block::List(list) => render_list(list, doc, ctx, out),
        Block::Table {
            headers,
            aligns,
            rows,
        } => {
            out.push_str("<table><thead><tr>");
            for (idx, header) in headers.iter().enumerate() {
                out.push_str("<th");
                push_align(aligns[idx], out);
                out.push('>');
                let inlines = parse_inlines(header, &doc.refs, false);
                render_inlines(&inlines, doc, ctx, out);
                out.push_str("</th>");
            }
            out.push_str("</tr></thead><tbody>\n");
            for row in rows {
                out.push_str("<tr>");
                for (idx, cell) in row.iter().enumerate() {
                    out.push_str("<td");
                    push_align(aligns[idx], out);
                    out.push('>');
                    let inlines = parse_inlines(cell, &doc.refs, false);
                    render_inlines(&inlines, doc, ctx, out);
                    out.push_str("</td>");
                }
                out.push_str("</tr>\n");
            }
            out.push_str("</tbody></table>\n");
        }
    }
}

fn push_align(align: Align, out: &mut String) {
    match align {
        Align::None => {}
        Align::Left => out.push_str(" style=\"text-align: left\""),
        Align::Center => out.push_str(" style=\"text-align: center\""),
        Align::Right => out.push_str(" style=\"text-align: right\""),
    }
}

fn render_list(list: &ListData, doc: &Document, ctx: &RenderContext<'_>, out: &mut String) {
    match list.start {
        None => out.push_str("<ul>\n"),
        Some(1) => out.push_str("<ol>\n"),
        Some(n) => out.push_str(&format!("<ol start=\"{}\">\n", n)),
    }
    for item in &list.items {
        if item.is_empty() {
            out.push_str("<li></li>\n");
            continue;
        }
        if list.loose {
            out.push_str("<li>\n");
            render_blocks(item, doc, ctx, false, out);
            out.push_str("</li>\n");
        } else {
            out.push_str("<li>");
            // Tight lists suppress paragraph tags; a paragraph that is
            // followed by another block still contributes its trailing
            // newline.
            for (idx, block) in item.iter().enumerate() {
                let is_para = matches!(block, Block::Paragraph(_));
                render_block(block, doc, ctx, true, out);
                if is_para && idx + 1 < item.len() {
                    out.push('\n');
                }
            }
            out.push_str("</li>\n");
        }
    }
    match list.start {
        None => out.push_str("</ul>\n"),
        Some(_) => out.push_str("</ol>\n"),
    }
}

// ---------------------------------------------------------------------------
// Image extraction (for media validation)

fn collect_images_blocks(blocks: &[Block], doc: &Document, out: &mut Vec<String>) {
    for block in blocks {
        match block {
            Block::Paragraph(text) | Block::Heading { text, .. } => {
                let inlines = parse_inlines(text, &doc.refs, false);
                collect_images_inlines(&inlines, out);
            }
            Block::Blockquote(inner) => collect_images_blocks(inner, doc, out),
            Block::List(list) => {
                for item in &list.items {
                    collect_images_blocks(item, doc, out);
                }
            }
            Block::Table { headers, rows, .. } => {
                for cell in headers.iter().chain(rows.iter().flatten()) {
                    let inlines = parse_inlines(cell, &doc.refs, false);
                    collect_images_inlines(&inlines, out);
                }
            }
            _ => {}
        }
    }
}

fn collect_images_inlines(nodes: &[Inline], out: &mut Vec<String>) {
    for node in nodes {
        match node {
            Inline::Image { dest, alt, .. } => {
                out.push(dest.clone());
                collect_images_inlines(alt, out);
            }
            Inline::Link { children, .. } => collect_images_inlines(children, out),
            Inline::Emphasis(c) | Inline::Strong(c) => collect_images_inlines(c, out),
            _ => {}
        }
    }
}
