use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Component, Path, PathBuf};

use serde::{Deserialize, Serialize};
use walkdir::WalkDir;

use crate::error::{Error, MissingMedia, Result};
use crate::markdown;
use crate::types::{Hash, Performance};

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CardLocation {
    pub file_path: String,
    pub line_start: usize,
    pub line_end: usize,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum CardContent {
    Basic { question: String, answer: String },
    Cloze { text: String, start: usize, end: usize },
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Card {
    pub hash: Hash,
    pub family_hash: Option<Hash>,
    pub deck_name: String,
    pub location: CardLocation,
    pub content: CardContent,
    pub performance: Option<Performance>,
}

#[derive(Debug, Clone)]
pub struct Collection {
    pub root: PathBuf,
    pub cards: BTreeMap<Hash, Card>,
    pub macros: Vec<(String, String)>,
}

#[derive(Debug, Deserialize)]
struct Frontmatter {
    name: Option<String>,
}

impl Collection {
    pub fn load(root: PathBuf) -> Result<Self> {
        let macros = load_macros(&root)?;
        let mut cards: BTreeMap<Hash, Card> = BTreeMap::new();
        for entry in WalkDir::new(&root) {
            let entry = entry?;
            let path = entry.path();
            if path.is_file()
                && path
                    .extension()
                    .is_some_and(|ext| ext == std::ffi::OsStr::new("md"))
            {
                let parsed = parse_deck_file(path)?;
                for card in parsed {
                    cards.entry(card.hash).or_insert(card);
                }
            }
        }
        let collection = Collection { root, cards, macros };
        collection.validate_media()?;
        Ok(collection)
    }

    fn validate_media(&self) -> Result<()> {
        let mut missing: BTreeSet<MissingMedia> = BTreeSet::new();
        for card in self.cards.values() {
            let canon_file = fs::canonicalize(&card.location.file_path)?;
            let rel_file = canon_file.strip_prefix(&self.root)?;
            let rel_dir = rel_file.parent().unwrap_or_else(|| Path::new(""));
            let mut media_refs: Vec<String> = Vec::new();
            match &card.content {
                CardContent::Basic { question, answer } => {
                    media_refs.extend(markdown::extract_image_destinations(question));
                    media_refs.extend(markdown::extract_image_destinations(answer));
                }
                CardContent::Cloze { text, .. } => {
                    media_refs.extend(markdown::extract_image_destinations(text));
                }
            }
            for media in media_refs {
                if !media_exists(&self.root, rel_dir, &media) {
                    missing.insert(MissingMedia {
                        media,
                        file_path: card.location.file_path.clone(),
                        line: card.location.line_start,
                    });
                }
            }
        }
        if missing.is_empty() {
            Ok(())
        } else {
            Err(Error::MissingMedia(missing))
        }
    }
}

fn load_macros(root: &Path) -> Result<Vec<(String, String)>> {
    let path = root.join("macros.tex");
    if !path.exists() {
        return Ok(Vec::new());
    }
    let content = fs::read_to_string(&path)?;
    let mut macros = Vec::new();
    for line in content.lines() {
        if line.starts_with('%') {
            continue;
        }
        if let Some((name, definition)) = line.split_once(' ') {
            macros.push((name.to_string(), definition.to_string()));
        }
    }
    Ok(macros)
}

fn media_exists(root: &Path, rel_card_dir: &Path, media: &str) -> bool {
    if media.is_empty() {
        return false;
    }
    if let Some(rel) = media.strip_prefix("@/") {
        let rel_path = Path::new(rel);
        if rel_path.is_absolute() {
            return false;
        }
        if rel_path
            .components()
            .any(|c| matches!(c, Component::ParentDir | Component::RootDir | Component::Prefix(_)))
        {
            return false;
        }
        return root.join(rel_path).exists();
    }
    let media_path = Path::new(media);
    if media_path.is_absolute() {
        return false;
    }
    let candidate = root.join(rel_card_dir).join(media_path);
    match fs::canonicalize(&candidate) {
        Ok(canon) => canon.starts_with(root),
        Err(_) => false,
    }
}

fn extract_frontmatter(content: &str) -> Result<(Option<String>, String)> {
    let lines: Vec<&str> = content.lines().collect();
    if lines.is_empty() || lines[0].trim() != "---" {
        return Ok((None, content.to_string()));
    }
    let Some(close_offset) = lines[1..].iter().position(|l| l.trim() == "---") else {
        return Err(Error::FrontmatterNoClosing);
    };
    let close = close_offset + 1;
    let toml_text = lines[1..close].join("\n");
    let parsed: Frontmatter = toml::from_str(&toml_text)?;
    let rest = lines[close + 1..].join("\n");
    Ok((parsed.name, rest))
}

fn parse_deck_file(path: &Path) -> Result<Vec<Card>> {
    let file_path = path.to_string_lossy().into_owned();
    let content = fs::read_to_string(path)?;
    let (fm_name, parse_content) = extract_frontmatter(&content)?;
    let deck_name = match fm_name {
        Some(name) => name,
        None => path
            .file_stem()
            .and_then(|s| s.to_str())
            .unwrap_or("None")
            .to_string(),
    };
    parse_cards(&parse_content, &deck_name, &file_path)
}

enum State {
    Idle,
    Question { text: String, start: usize },
    Answer { question: String, text: String, start: usize },
    Cloze { text: String, start: usize },
}

fn is_separator(line: &str) -> bool {
    line.trim() == "---"
}

fn make_basic(
    question: String,
    answer: String,
    deck_name: &str,
    file_path: &str,
    start: usize,
    end: usize,
) -> Card {
    let question = question.trim().to_string();
    let answer = answer.trim().to_string();
    let hash = Hash::of_basic(&question, &answer);
    Card {
        hash,
        family_hash: None,
        deck_name: deck_name.to_string(),
        location: CardLocation {
            file_path: file_path.to_string(),
            line_start: start,
            line_end: end,
        },
        content: CardContent::Basic { question, answer },
        performance: None,
    }
}

fn make_clozes(
    text: String,
    deck_name: &str,
    file_path: &str,
    start: usize,
    end: usize,
) -> Result<Vec<Card>> {
    let text = text.trim().to_string();
    let (cleaned, ranges) = parse_cloze_text(&text);
    if ranges.is_empty() {
        return Err(Error::Parse {
            message: "Cloze card must contain at least one cloze deletion.",
            file_path: file_path.to_string(),
            line: start + 1,
        });
    }
    let family = Hash::of_cloze_family(&cleaned);
    let mut out = Vec::new();
    for (cstart, cend) in ranges {
        out.push(Card {
            hash: Hash::of_cloze(&cleaned, cstart, cend),
            family_hash: Some(family),
            deck_name: deck_name.to_string(),
            location: CardLocation {
                file_path: file_path.to_string(),
                line_start: start,
                line_end: end,
            },
            content: CardContent::Cloze {
                text: cleaned.clone(),
                start: cstart,
                end: cend,
            },
            performance: None,
        });
    }
    Ok(out)
}

/// Strip cloze brackets from `text`, returning the cleaned text and the
/// (byte start, byte end) range of each deletion.  `\[` and `\]` are
/// escaped literals; a `[` while a deletion is already open moves the
/// start; a stray `]` is dropped.
fn parse_cloze_text(text: &str) -> (String, Vec<(usize, usize)>) {
    let mut cleaned = String::new();
    let mut ranges: Vec<(usize, usize)> = Vec::new();
    let mut cloze_start: Option<usize> = None;
    let mut chars = text.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch == '\\' && matches!(chars.peek(), Some('[') | Some(']')) {
            cleaned.push(chars.next().unwrap());
        } else if ch == '[' {
            cloze_start = Some(cleaned.len());
        } else if ch == ']' {
            if let Some(start) = cloze_start.take() {
                ranges.push((start, cleaned.len().wrapping_sub(1)));
            }
        } else {
            cleaned.push(ch);
        }
    }
    (cleaned, ranges)
}

fn parse_error(message: &'static str, file_path: &str, line: usize) -> Error {
    Error::Parse {
        message,
        file_path: file_path.to_string(),
        line,
    }
}

fn parse_cards(content: &str, deck_name: &str, file_path: &str) -> Result<Vec<Card>> {
    let lines: Vec<&str> = content.lines().collect();
    let mut cards: Vec<Card> = Vec::new();
    let mut state = State::Idle;

    for (idx, line) in lines.iter().enumerate() {
        let line = *line;
        if let Some(rest) = line.strip_prefix("Q:") {
            let initial = rest.trim().to_string();
            state = match state {
                State::Idle => State::Question {
                    text: initial,
                    start: idx,
                },
                State::Question { .. } => {
                    return Err(parse_error("New question without answer.", file_path, idx + 1));
                }
                State::Answer {
                    question,
                    text,
                    start,
                } => {
                    cards.push(make_basic(question, text, deck_name, file_path, start, idx));
                    State::Question {
                        text: initial,
                        start: idx,
                    }
                }
                State::Cloze { text, start } => {
                    cards.extend(make_clozes(text, deck_name, file_path, start, idx)?);
                    State::Question {
                        text: initial,
                        start: idx,
                    }
                }
            };
        } else if let Some(rest) = line.strip_prefix("A:") {
            let initial = rest.trim().to_string();
            state = match state {
                State::Idle => {
                    return Err(parse_error(
                        "Found answer tag without a question.",
                        file_path,
                        idx + 1,
                    ));
                }
                State::Question { text, start } => State::Answer {
                    question: text,
                    text: initial,
                    start,
                },
                State::Answer { .. } => {
                    return Err(parse_error(
                        "Found answer tag while reading an answer.",
                        file_path,
                        idx + 1,
                    ));
                }
                State::Cloze { .. } => {
                    return Err(parse_error(
                        "Found answer tag while reading a cloze card.",
                        file_path,
                        idx + 1,
                    ));
                }
            };
        } else if let Some(rest) = line.strip_prefix("C:") {
            let initial = rest.trim().to_string();
            state = match state {
                State::Idle => State::Cloze {
                    text: initial,
                    start: idx,
                },
                State::Question { .. } => {
                    return Err(parse_error(
                        "Found cloze tag while reading a question.",
                        file_path,
                        idx + 1,
                    ));
                }
                State::Answer {
                    question,
                    text,
                    start,
                } => {
                    cards.push(make_basic(question, text, deck_name, file_path, start, idx));
                    State::Cloze {
                        text: initial,
                        start: idx,
                    }
                }
                State::Cloze { text, start } => {
                    cards.extend(make_clozes(text, deck_name, file_path, start, idx)?);
                    State::Cloze {
                        text: initial,
                        start: idx,
                    }
                }
            };
        } else if is_separator(line) {
            state = match state {
                State::Idle => State::Idle,
                State::Question { .. } => {
                    return Err(parse_error(
                        "Found flashcard separator while reading a question.",
                        file_path,
                        idx + 1,
                    ));
                }
                State::Answer {
                    question,
                    text,
                    start,
                } => {
                    cards.push(make_basic(question, text, deck_name, file_path, start, idx));
                    State::Idle
                }
                State::Cloze { text, start } => {
                    cards.extend(make_clozes(text, deck_name, file_path, start, idx)?);
                    State::Idle
                }
            };
        } else {
            match &mut state {
                State::Idle => {}
                State::Question { text, .. } => {
                    text.push('\n');
                    text.push_str(line);
                }
                State::Answer { text, .. } => {
                    text.push('\n');
                    text.push_str(line);
                }
                State::Cloze { text, .. } => {
                    text.push('\n');
                    text.push_str(line);
                }
            }
        }
    }

    let last_line = lines.len().saturating_sub(1);
    match state {
        State::Idle => {}
        State::Question { .. } => {
            return Err(parse_error(
                "File ended while reading a question without an answer.",
                file_path,
                lines.len(),
            ));
        }
        State::Answer {
            question,
            text,
            start,
        } => {
            cards.push(make_basic(
                question,
                text,
                deck_name,
                file_path,
                start,
                last_line,
            ));
        }
        State::Cloze { text, start } => {
            cards.extend(make_clozes(text, deck_name, file_path, start, last_line)?);
        }
    }
    Ok(cards)
}
RS

