    for (idx, line) in lines.iter().enumerate() {
        let line = *line;
        if let Some(rest) = line.strip_prefix("Q:") {
            let initial = rest.trim().to_string();
            state = match state {
                State::Idle => State::Question {
                    text: initial,
                    start: idx,
                },
                State::Question { .. } => {
                    return Err(parse_error("New question without answer.", file_path, idx + 1));
                }
                State::Answer {
                    question,
                    text,
                    start,
                } => {
                    cards.push(make_basic(question, text, deck_name, file_path, start, idx));
                    State::Question {
                        text: initial,
                        start: idx,
                    }
                }
                State::Cloze { text, start } => {
                    cards.extend(make_clozes(text, deck_name, file_path, start, idx)?);
                    State::Question {
                        text: initial,
                        start: idx,
                    }
                }
            };
        } else if let Some(rest) = line.strip_prefix("A:") {
            let initial = rest.trim().to_string();
            state = match state {
                State::Idle => {
                    return Err(parse_error(
                        "Found answer tag without a question.",
                        file_path,
                        idx + 1,
                    ));
                }
                State::Question { text, start } => State::Answer {
                    question: text,
                    text: initial,
                    start,
                },
                State::Answer { .. } => {
                    return Err(parse_error(
                        "Found answer tag while reading an answer.",
                        file_path,
                        idx + 1,
                    ));
                }
                State::Cloze { .. } => {
                    return Err(parse_error(
                        "Found answer tag while reading a cloze card.",
                        file_path,
                        idx + 1,
                    ));
                }
            };
        } else if let Some(rest) = line.strip_prefix("C:") {
            let initial = rest.trim().to_string();
            state = match state {
                State::Idle => State::Cloze {
                    text: initial,
                    start: idx,
                },
                State::Question { .. } => {
                    return Err(parse_error(
                        "Found cloze tag while reading a question.",
                        file_path,
                        idx + 1,
                    ));
                }
                State::Answer {
                    question,
                    text,
                    start,
                } => {
                    cards.push(make_basic(question, text, deck_name, file_path, start, idx));
                    State::Cloze {
                        text: initial,
                        start: idx,
                    }
                }
                State::Cloze { text, start } => {
                    cards.extend(make_clozes(text, deck_name, file_path, start, idx)?);
                    State::Cloze {
                        text: initial,
                        start: idx,
                    }
                }
            };
        } else if is_separator(line) {
            state = match state {
                State::Idle => State::Idle,
                State::Question { .. } => {
                    return Err(parse_error(
                        "Found flashcard separator while reading a question.",
                        file_path,
                        idx + 1,
                    ));
                }
                State::Answer {
                    question,
                    text,
                    start,
                } => {
                    cards.push(make_basic(question, text, deck_name, file_path, start, idx));
                    State::Idle
                }
                State::Cloze { text, start } => {
                    cards.extend(make_clozes(text, deck_name, file_path, start, idx)?);
                    State::Idle
                }
            };
        } else {
            match &mut state {
                State::Idle => {}
                State::Question { text, .. } => {
                    text.push('\n');
                    text.push_str(line);
                }
                State::Answer { text, .. } => {
                    text.push('\n');
                    text.push_str(line);
                }
                State::Cloze { text, .. } => {
                    text.push('\n');
                    text.push_str(line);
                }
            }
        }
    }

    let last_line = lines.len().saturating_sub(1);
    match state {
        State::Idle => {}
        State::Question { .. } => {
            return Err(parse_error(
                "File ended while reading a question without an answer.",
                file_path,
                lines.len(),
            ));
        }
        State::Answer {
            question,
            text,
            start,
        } => {
            cards.push(make_basic(
                question,
                text,
                deck_name,
                file_path,
                start,
                last_line,
            ));
        }
        State::Cloze { text, start } => {
            cards.extend(make_clozes(text, deck_name, file_path, start, last_line)?);
        }
    }
    Ok(cards)
}
RS
"}

