use crate::types::{Grade, Performance, Timestamp};

const W: [f64; 19] = [
    0.40255, 1.18385, 3.173, 15.69105, 7.1949, 0.5345, 1.4604, 0.0046, 1.54575, 0.1192, 1.01925,
    1.9395, 0.11, 0.29605, 2.2698, 0.2315, 2.9898, 0.51655, 0.6621,
];
const DECAY: f64 = -0.5;
const FACTOR: f64 = 19.0 / 81.0;
const REQUEST_RETENTION: f64 = 0.9;
const MAX_INTERVAL_DAYS: i64 = 256;

fn initial_stability(grade: Grade) -> f64 {
    W[(grade.value() - 1) as usize]
}

fn initial_difficulty(grade: Grade) -> f64 {
    let d = W[4] - (W[5] * (grade.value() as f64 - 1.0)).exp() + 1.0;
    d.clamp(1.0, 10.0)
}

fn next_difficulty(difficulty: f64, grade: Grade) -> f64 {
    let delta = -W[6] * (grade.value() as f64 - 3.0);
    let damped = difficulty + delta * (10.0 - difficulty) / 9.0;
    let reverted = W[7] * initial_difficulty(Grade::Easy) + (1.0 - W[7]) * damped;
    reverted.clamp(1.0, 10.0)
}

fn retrievability(elapsed_days: f64, stability: f64) -> f64 {
    (1.0 + FACTOR * elapsed_days / stability).powf(DECAY)
}

fn next_recall_stability(difficulty: f64, stability: f64, r: f64, grade: Grade) -> f64 {
    let hard_factor = if grade == Grade::Hard { W[15] } else { 1.0 };
    let easy_factor = if grade == Grade::Easy { W[16] } else { 1.0 };
    stability
        * (1.0
            + W[8].exp()
                * (11.0 - difficulty)
                * stability.powf(-W[9])
                * ((W[10] * (1.0 - r)).exp() - 1.0)
                * hard_factor
                * easy_factor)
}

fn next_forget_stability(difficulty: f64, stability: f64, r: f64) -> f64 {
    let s = W[11]
        * difficulty.powf(-W[12])
        * ((stability + 1.0).powf(W[13]) - 1.0)
        * (W[14] * (1.0 - r)).exp();
    s.min(stability)
}

fn next_interval(stability: f64) -> f64 {
    stability / FACTOR * (REQUEST_RETENTION.powf(1.0 / DECAY) - 1.0)
}

pub fn next_performance(
    old: Option<&Performance>,
    grade: Grade,
    now: Timestamp,
) -> Performance {
    let (stability, difficulty, review_count) = match old {
        None => (
            initial_stability(grade),
            initial_difficulty(grade),
            1usize,
        ),
        Some(old) => {
            let elapsed_days = old.last_reviewed_at.date().days_until(now.date()) as f64;
            let r = retrievability(elapsed_days, old.stability);
            let difficulty = next_difficulty(old.difficulty, grade);
            let stability = if grade == Grade::Forgot {
                next_forget_stability(old.difficulty, old.stability, r)
            } else {
                next_recall_stability(old.difficulty, old.stability, r, grade)
            };
            (stability, difficulty, old.review_count + 1)
        }
    };
    let interval_raw = next_interval(stability);
    let interval_days = (interval_raw.round() as i64).clamp(1, MAX_INTERVAL_DAYS);
    Performance {
        last_reviewed_at: now,
        stability,
        difficulty,
        interval_raw,
        interval_days,
        due_date: now.date().add_days(interval_days),
        review_count,
    }
}
RS
"}

