{"command":"cat > src/drill.rs <<'RS'
use std::collections::{BTreeSet, VecDeque};
use std::path::Path;

use rand::seq::SliceRandom;

use crate::collection::{Card, CardContent, Collection};
use crate::db::{Db, SessionReview};
use crate::error::Result;
use crate::fsrs;
use crate::markdown::{self, RenderContext};
use crate::types::{date_today, Grade, Hash, Timestamp};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AnswerControls {
    Full,
    Binary,
}

#[derive(Debug, Clone)]
pub struct DrillOptions {
    pub card_limit: Option<usize>,
    pub new_card_limit: Option<usize>,
    pub from_deck: Option<String>,
    pub bury_siblings: bool,
    pub answer_controls: AnswerControls,
    pub port: u16,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Action {
    Reveal,
    Undo,
    End,
    Forgot,
    Hard,
    Good,
    Easy,
    Shutdown,
}

impl Action {
    pub fn grade(&self) -> Option<Grade> {
        match self {
            Action::Forgot => Some(Grade::Forgot),
            Action::Hard => Some(Grade::Hard),
            Action::Good => Some(Grade::Good),
            Action::Easy => Some(Grade::Easy),
            _ => None,
        }
    }
}

pub struct DrillSession {
    pub collection: Collection,
    queue: VecDeque<Hash>,
    total_cards: usize,
    reviews: Vec<SessionReview>,
    answer_revealed: bool,
    started_at: Timestamp,
    ended_at: Option<Timestamp>,
    answer_controls: AnswerControls,
    port: u16,
}

impl DrillSession {
    pub fn new(collection: Collection, options: &DrillOptions, started_at: Timestamp) -> Self {
        let today = date_today();
        let mut due: Vec<Hash> = Vec::new();
        for card in collection.cards.values() {
            if let Some(deck) = &options.from_deck {
                if &card.deck_name != deck {
                    continue;
                }
            }
            let is_due = match &card.performance {
                None => true,
                Some(perf) => perf.due_date <= today,
            };
            if is_due {
                due.push(card.hash);
            }
        }
        if let Some(limit) = options.card_limit {
            due.truncate(limit);
        }
        if let Some(limit) = options.new_card_limit {
            let mut seen_new = 0usize;
            due.retain(|hash| {
                let is_new = collection
                    .cards
                    .get(hash)
                    .map(|c| c.performance.is_none())
                    .unwrap_or(true);
                if is_new {
                    if seen_new < limit {
                        seen_new += 1;
                        true
                    } else {
                        false
                    }
                } else {
                    true
                }
            });
        }
        if options.bury_siblings {
            let mut seen_families: BTreeSet<Hash> = BTreeSet::new();
            due.retain(|hash| {
                match collection.cards.get(hash).and_then(|c| c.family_hash) {
                    Some(family) => seen_families.insert(family),
                    None => true,
                }
            });
        }
        due.shuffle(&mut rand::thread_rng());
        let total_cards = due.len();
        DrillSession {
            collection,
            queue: due.into(),
            total_cards,
            reviews: Vec::new(),
            answer_revealed: false,
            started_at,
            ended_at: None,
            answer_controls: options.answer_controls,
            port: options.port,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.total_cards == 0
    }

    pub fn is_finished(&self) -> bool {
        self.ended_at.is_some()
    }

    fn cards_reviewed(&self) -> usize {
        self.total_cards.saturating_sub(self.queue.len())
    }

    fn current_card(&self) -> Option<&Card> {
        self.queue.front().and_then(|h| self.collection.cards.get(h))
    }

    /// Apply an action.  Returns true when the server should shut down.
    pub fn handle_action(&mut self, db: &Db, action: Action) -> Result<bool> {
        match action {
            Action::Reveal => {
                if self.ended_at.is_none() {
                    self.answer_revealed = true;
                }
                Ok(false)
            }
            Action::Undo => {
                self.undo(db)?;
                Ok(false)
            }
            Action::End => {
                self.end_session(db, Timestamp::now())?;
                Ok(false)
            }
            Action::Shutdown => Ok(self.ended_at.is_some()),
            Action::Forgot | Action::Hard | Action::Good | Action::Easy => {
                let grade = action.grade().unwrap();
                if !self.answer_revealed || self.ended_at.is_some() {
                    return Ok(false);
                }
                let Some(hash) = self.queue.pop_front() else {
                    return Ok(false);
                };
                let now = Timestamp::now();
                let performance = {
                    let card = self.collection.cards.get(&hash);
                    let old = card.and_then(|c| c.performance.as_ref());
                    fsrs::next_performance(old, grade, now)
                };
                if let Some(card) = self.collection.cards.get_mut(&hash) {
                    card.performance = Some(performance.clone());
                }
