            started_at,
            ended_at: None,
            answer_controls: options.answer_controls,
            port: options.port,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.total_cards == 0
    }

    pub fn is_finished(&self) -> bool {
        self.ended_at.is_some()
    }

    fn cards_reviewed(&self) -> usize {
        self.total_cards.saturating_sub(self.queue.len())
    }

    fn current_card(&self) -> Option<&Card> {
        self.queue.front().and_then(|h| self.collection.cards.get(h))
    }

    /// Apply an action.  Returns true when the server should shut down.
    pub fn handle_action(&mut self, db: &Db, action: Action) -> Result<bool> {
        match action {
            Action::Reveal => {
                if self.ended_at.is_none() {
                    self.answer_revealed = true;
                }
                Ok(false)
            }
            Action::Undo => {
                self.undo(db)?;
                Ok(false)
            }
            Action::End => {
                self.end_session(db, Timestamp::now())?;
                Ok(false)
            }
            Action::Shutdown => Ok(self.ended_at.is_some()),
            Action::Forgot | Action::Hard | Action::Good | Action::Easy => {
                let grade = action.grade().unwrap();
                if !self.answer_revealed || self.ended_at.is_some() {
                    return Ok(false);
                }
                let Some(hash) = self.queue.pop_front() else {
                    return Ok(false);
                };
                let now = Timestamp::now();
                let performance = {
                    let card = self.collection.cards.get(&hash);
                    let old = card.and_then(|c| c.performance.as_ref());
                    fsrs::next_performance(old, grade, now)
                };
                if let Some(card) = self.collection.cards.get_mut(&hash) {
                    card.performance = Some(performance.clone());
                }
                self.reviews.push(SessionReview {
                    hash,
                    reviewed_at: now,
                    grade,
                    performance,
                });
                if !grade.is_pass() {
                    self.queue.push_back(hash);
                }
                self.answer_revealed = false;
                if self.queue.is_empty() {
                    self.end_session(db, now)?;
                }
                Ok(false)
            }
        }
    }

    fn undo(&mut self, db: &Db) -> Result<()> {
        let Some(review) = self.reviews.pop() else {
            return Ok(());
        };
        let hash = review.hash;
        let stored = db.get_performance(hash)?;
        if let Some(card) = self.collection.cards.get_mut(&hash) {
            card.performance = stored;
        }
        self.queue.retain(|h| *h != hash);
        self.queue.push_front(hash);
        self.answer_revealed = false;
        self.ended_at = None;
        Ok(())
    }

    fn end_session(&mut self, db: &Db, ended_at: Timestamp) -> Result<()> {
        db.save_session(self.started_at, ended_at, &self.reviews)?;
        self.ended_at = Some(ended_at);
        Ok(())
    }

    pub fn render_page(&self) -> String {
        if let Some(ended_at) = self.ended_at {
            return self.render_finished(ended_at);
        }
        let Some(card) = self.current_card() else {
            // A session whose final save failed has an empty queue and no
            // end time.  Show the finished page using the start time
            // rather than failing.
            return self.render_finished(self.started_at);
        };
        let progress = if self.total_cards == 0 {
            0
        } else {
            self.cards_reviewed() * 100 / self.total_cards
        };
        let ctx = RenderContext {
            root: &self.collection.root,
            card_file_path: Path::new(&card.location.file_path),
            port: self.port,
        };
        let content = match &card.content {
            CardContent::Basic { question, answer } => {
                let q = markdown::render_markdown(question, &ctx);
                let a = if self.answer_revealed {
                    markdown::render_markdown(answer, &ctx)
                } else {
                    String::new()
                };
                format!(
                    "<div class=\"question rich-text\">{}</div><div class=\"answer rich-text\">{}</div>",
                    q, a
                )
            }
            CardContent::Cloze { text, start, end } => {
                let transformed = cloze_transform(text, *start, *end, self.answer_revealed);
                let rendered = markdown::render_markdown(&transformed, &ctx);
                format!("<div class=\"prompt rich-text\">{}</div>", rendered)
            }
        };
        let body = format!(
            "<div class=\"root\"><div class=\"header\"><div class=\"progress-bar\"><div class=\"progress-fill\" style=\"width: {}%;\"></div></div></div><div class=\"card-container\"><div class=\"card\"><div class=\"card-header\"><h1>{}</h1></div><div class=\"card-content\">{}</div></div></div><div class=\"controls\">{}</div></div>",
            progress,
            escape_html_text(&card.deck_name),
            content,
            self.render_controls()
        );
        page(&body)
    }

    fn render_controls(&self) -> String {
        let undo = if self.reviews.is_empty() {
            "<input id=\"undo\" type=\"submit\" name=\"action\" value=\"Undo\" disabled>".to_string()
        } else {
            "<input id=\"undo\" type=\"submit\" name=\"action\" value=\"Undo\" title=\"Undo last action. Shortcut: u.\">".to_string()
        };
        let middle = if !self.answer_revealed {
            "<input id=\"reveal\" type=\"submit\" name=\"action\" value=\"Reveal\" title=\"Show the answer. Shortcut: space.\">".to_string()
        } else {
            match self.answer_controls {
                AnswerControls::Full => "<div class=\"grades\"><input id=\"forgot\" type=\"submit\" name=\"action\" value=\"Forgot\" title=\"Mark card as forgotten. Shortcut: 1.\"><input id=\"hard\" type=\"submit\" name=\"action\" value=\"Hard\" title=\"Mark card as difficult. Shortcut: 2.\"><input id=\"good\" type=\"submit\" name=\"action\" value=\"Good\" title=\"Mark card as remembered well. Shortcut: 3.\"><input id=\"easy\" type=\"submit\" name=\"action\" value=\"Easy\" title=\"Mark card as very easy. Shortcut: 4.\"></div>".to_string(),
                AnswerControls::Binary => "<div class=\"grades\"><input id=\"forgot\" type=\"submit\" name=\"action\" value=\"Forgot\" title=\"Mark card as forgotten.\"><input id=\"good\" type=\"submit\" name=\"action\" value=\"Good\" title=\"Mark card as remembered.\"></div>".to_string(),
            }
        };
        format!(
            "<form action=\"/\" method=\"post\">{undo}<div class=\"spacer\"></div>{middle}<div class=\"spacer\"></div><input id=\"end\" type=\"submit\" name=\"action\" value=\"End\" title=\"End the session (changes are saved)\"></form>"
        )
    }

    fn render_finished(&self, ended_at: Timestamp) -> String {
        let reviewed = self.cards_reviewed();
        let duration = (ended_at.0 - self.started_at.0).num_seconds();
        let pace = if reviewed > 0 {
            duration as f64 / reviewed as f64
        } else {
            0.0
        };
        let body = format!(
            "<div class=\"finished\"><h1>Session Completed 🎉</h1><div class=\"summary\">Reviewed {} cards in {} seconds.</div><h2>Session Stats</h2><div class=\"stats\"><table><tbody><tr><td class=\"key\">Total Cards</td><td class=\"val\">{}</td></tr><tr><td class=\"key\">Cards Reviewed</td><td class=\"val\">{}</td></tr><tr><td class=\"key\">Started</td><td class=\"val\">{}</td></tr><tr><td class=\"key\">Finished</td><td class=\"val\">{}</td></tr><tr><td class=\"key\">Duration (seconds)</td><td class=\"val\">{}</td></tr><tr><td class=\"key\">Pace (s/card)</td><td class=\"val\">{:.2}</td></tr></tbody></table></div><div class=\"shutdown-container\"><form action=\"/\" method=\"post\"><input class=\"shutdown-button\" id=\"shutdown\" type=\"submit\" name=\"action\" value=\"Shutdown\" title=\"Shut down the server\"></form></div></div>",
            reviewed,
            duration,
            self.total_cards,
            reviewed,
            self.started_at.format_display(),
            ended_at.format_display(),
            duration,
            pace,
        );
        page(&body)
    }
}

fn cloze_transform(text: &str, start: usize, end: usize, revealed: bool) -> String {
    let before = text.get(..start).unwrap_or("");
    let segment = text.get(start..=end).unwrap_or("");
    let after = if end == usize::MAX {
        text.get(start..).unwrap_or("")
    } else {
        text.get(end.wrapping_add(1)..)
            .unwrap_or_else(|| text.get(start..).unwrap_or(""))
    };
    if revealed {
        format!(
            "{}<span class='cloze-reveal'>{}</span>{}",
            before,
            segment.trim(),
            after
        )
    } else {
        format!(
            "{}<span class='cloze'>.............</span>{}",
            before, after
        )
    }
}

pub fn escape_html_text(s: &str) -> String {
    let mut out = String::new();
    for ch in s.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(ch),
        }
    }
    out
}

const HEAD: &str = "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>hashcards</title><link rel=\"stylesheet\" href=\"/katex/katex.css\"><link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css\"><script defer src=\"/katex/katex.js\"></script><script defer src=\"/katex/mhchem.js\"></script><script defer src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js\"></script><link rel=\"stylesheet\" href=\"/style.css\"><style>.card-content { opacity: 0; }</style><noscript><style>.card-content { opacity: 1; }</style></noscript></head><body>";
const TAIL: &str = "<script src=\"/script.js\"></script></body></html>";

fn page(body: &str) -> String {
    format!("{}{}{}", HEAD, body, TAIL)
}
