struct AppState {
    session: Mutex<DrillSession>,
    db: Mutex<Db>,
    root: PathBuf,
    macros: Vec<(String, String)>,
    shutdown: AtomicBool,
}

struct Request {
    method: String,
    raw_path: String,
    version: String,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

impl Request {
    fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(k, _)| k.eq_ignore_ascii_case(name))
            .map(|(_, v)| v.as_str())
    }
    fn keep_alive(&self) -> bool {
        let conn = self.header("connection").unwrap_or("");
        let mut tokens = conn.split(',').map(|t| t.trim().to_ascii_lowercase());
        if tokens.any(|t| t == "close") {
            return false;
        }
        if self.version == "HTTP/1.1" {
            true
        } else {
            self.header("connection")
                .is_some_and(|v| v.to_ascii_lowercase().contains("keep-alive"))
        }
    }
}

struct Response {
    status: u16,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

impl Response {
    fn new(status: u16, content_type: &str, body: Vec<u8>) -> Self {
        Response {
            status,
            headers: vec![("content-type".to_string(), content_type.to_string())],
            body,
        }
    }
    fn with_header(mut self, name: &str, value: &str) -> Self {
        self.headers.push((name.to_string(), value.to_string()));
        self
    }
}

fn reason(status: u16) -> &'static str {
    match status {
        200 => "OK",
        303 => "See Other",
        400 => "Bad Request",
        404 => "Not Found",
        405 => "Method Not Allowed",
        413 => "Payload Too Large",
        415 => "Unsupported Media Type",
        422 => "Unprocessable Entity",
        500 => "Internal Server Error",
        _ => "OK",
    }
}

pub fn serve(
    listener: TcpListener,
    session: DrillSession,
    db: Db,
    open_browser: bool,
    host: &str,
    port: u16,
) -> Result<()> {
    let root = session.collection.root.clone();
    let macros = session.collection.macros.clone();
    let state = Arc::new(AppState {
        session: Mutex::new(session),
        db: Mutex::new(db),
        root,
        macros,
        shutdown: AtomicBool::new(false),
    });
    listener
        .set_nonblocking(true)
        .map_err(crate::error::Error::from)?;
    if open_browser {
        let url = format!("http://{}:{}/", host, port);
        let _ = std::process::Command::new("xdg-open")
            .arg(&url)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn();
    }
    while !state.shutdown.load(Ordering::SeqCst) {
        match listener.accept() {
            Ok((stream, _)) => {
                let state = Arc::clone(&state);
                std::thread::spawn(move || {
                    handle_connection(stream, state);
                });
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                std::thread::sleep(Duration::from_millis(5));
            }
            Err(_) => {
                std::thread::sleep(Duration::from_millis(5));
            }
        }
    }
    Ok(())
}

fn handle_connection(stream: TcpStream, state: Arc<AppState>) {
    let _ = stream.set_nodelay(true);
    let Ok(mut writer) = stream.try_clone() else {
        return;
    };
    let mut reader = BufReader::new(stream);
    loop {
        let Some(request) = read_request(&mut reader, &mut writer) else {
            return;
        };
        let keep_alive = request.keep_alive();
        let is_head = request.method == "HEAD";
        let (response, shutdown_after) = route(&request, &state);
        if !write_response(&mut writer, &response, keep_alive, is_head) {
            return;
        }
        let _ = writer.flush();
        if shutdown_after {
            state.shutdown.store(true, Ordering::SeqCst);
            return;
        }
        if !keep_alive || state.shutdown.load(Ordering::SeqCst) {
            return;
        }
    }
}

fn read_request(reader: &mut BufReader<TcpStream>, writer: &mut TcpStream) -> Option<Request> {
    let mut request_line = String::new();
    match reader.read_line(&mut request_line) {
        Ok(0) => return None,
        Ok(_) => {}
        Err(_) => return None,
    }
    let request_line = request_line.trim_end_matches(['\r', '\n']).to_string();
    let mut parts = request_line.split_whitespace();
    let (Some(method), Some(target), Some(version)) =
        (parts.next(), parts.next(), parts.next())
    else {
        send_bad_request(writer);
        return None;
    };
    if parts.next().is_some() || !(version == "HTTP/1.1" || version == "HTTP/1.0") {
        send_bad_request(writer);
        return None;
    }
    let mut headers: Vec<(String, String)> = Vec::new();
    loop {
        let mut line = String::new();
        match reader.read_line(&mut line) {
            Ok(0) => return None,
            Ok(_) => {}
            Err(_) => return None,
        }
        let line = line.trim_end_matches(['\r', '\n']);
        if line.is_empty() {
            break;
        }
        let Some((name, value)) = line.split_once(':') else {
            send_bad_request(writer);
            return None;
        };
        headers.push((name.trim().to_string(), value.trim().to_string()));
        if headers.len() > 200 {
            send_bad_request(writer);
            return None;
        }
    }
    let raw_path = extract_path(target);
    let mut body: Vec<u8> = Vec::new();
    let get_header = |name: &str| {
        headers
            .iter()
            .find(|(k, _)| k.eq_ignore_ascii_case(name))
            .map(|(_, v)| v.as_str())
    };
    if let Some(te) = get_header("transfer-encoding") {
        if te.to_ascii_lowercase().contains("chunked") {
            loop {
                let mut size_line = String::new();
                if reader.read_line(&mut size_line).is_err() {
                    return None;
                }
                let size_str = size_line.trim().split(';').next().unwrap_or("0");
                let Ok(size) = usize::from_str_radix(size_str, 16) else {
                    send_bad_request(writer);
                    return None;
                };
                if size == 0 {
                    // Read trailers until an empty line.
                    loop {
                        let mut trailer = String::new();
                        if reader.read_line(&mut trailer).is_err() {
                            return None;
                        }
                        if trailer == "\r\n" || trailer == "\n" || trailer.is_empty() {
                            break;
                        }
                    }
                    break;
                }
                let mut chunk = vec![0u8; size];
                if reader.read_exact(&mut chunk).is_err() {
                    return None;
                }
                body.extend_from_slice(&chunk);
                // CRLF after the chunk.
                let mut crlf = [0u8; 2];
                if reader.read_exact(&mut crlf).is_err() {
                    return None;
                }
                if body.len() > 32 * 1024 * 1024 {
                    return None;
                }
            }
        }
    } else if let Some(len_str) = get_header("content-length") {
        let Ok(len) = len_str.trim().parse::<usize>() else {
            send_bad_request(writer);
            return None;
        };
        if len > 32 * 1024 * 1024 {
            // Still need a request to produce the framework's 413 response.
            body = vec![0; len.min(2 * 1024 * 1024 + 1)];
            // Read and discard the rest would block; instead truncate the
            // recorded body.  The connection is closed after responding.
            let to_read = body.len();
            let mut limited = reader.take(to_read as u64);
            let _ = limited.read_to_end(&mut Vec::new());
        } else {
            body = vec![0u8; len];
            if reader.read_exact(&mut body).is_err() {
                return None;
            }
        }
    }
    Some(Request {
        method: method.to_string(),
        raw_path,
        version: version.to_string(),
        headers,
        body,
    })
}

fn extract_path(target: &str) -> String {
    let mut path = target;
    if let Some(rest) = target
        .strip_prefix("http://")
        .or_else(|| target.strip_prefix("https://"))
    {
        path = match rest.find('/') {
            Some(idx) => &rest[idx..],
            None => "/",
        };
    }
    // Drop a fragment; keep the query separate from routing.
    if let Some(idx) = path.find('#') {
        path = &path[..idx];
    }
    if let Some(idx) = path.find('?') {
        path = &path[..idx];
    }
    if path.is_empty() {
        "/".to_string()
    } else {
        path.to_string()
    }
}

fn send_bad_request(writer: &mut TcpStream) {
    let resp = Response {
        status: 400,
        headers: Vec::new(),
        body: Vec::new(),
    };
    let _ = write_response(writer, &resp, false, false);
}

fn write_response(writer: &mut TcpStream, resp: &Response, keep_alive: bool, is_head: bool) -> bool {
    let mut head = format!("HTTP/1.1 {} {}\r\n", resp.status, reason(resp.status));
    for (name, value) in &resp.headers {
        head.push_str(&format!("{}: {}\r\n", name, value));
    }
    head.push_str(&format!("content-length: {}\r\n", resp.body.len()));
    if !keep_alive {
        head.push_str("connection: close\r\n");
    }
    let date = Utc::now().format("%a, %d %b %Y %H:%M:%S GMT");
    head.push_str(&format!("date: {}\r\n", date));
    head.push_str("\r\n");
    if writer.write_all(head.as_bytes()).is_err() {
        return false;
    }
    if !is_head && writer.write_all(&resp.body).is_err() {
        return false;
    }
    true
}

fn percent_decode(s: &str) -> std::result::Result<String, ()> {
    let bytes = s.as_bytes();
    let mut out: Vec<u8> = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%'
            && i + 2 < bytes.len()
            && (bytes[i + 1] as char).is_ascii_hexdigit()
            && (bytes[i + 2] as char).is_ascii_hexdigit()
        {
            out.push(u8::from_str_radix(&s[i + 1..i + 3], 16).map_err(|_| ())?);
            i += 3;
        } else {
            out.push(bytes[i]);
            i += 1;
        }
    }
    String::from_utf8(out).map_err(|_| ())
}

fn invalid_url_response() -> Response {
    Response::new(
        400,
        "text/plain; charset=utf-8",
        b"Invalid URL: Invalid UTF-8 in `path`".to_vec(),
    )
}

fn fallback_404() -> Response {
    Response::new(404, "text/html; charset=utf-8", b"Not Found".to_vec())
}

fn plain_404(cache_no_cache: bool) -> Response {
    let r = Response::new(404, "text/plain", b"Not Found".to_vec());
    if cache_no_cache {
        r.with_header("cache-control", "no-cache")
    } else {
        r
    }
}

fn method_not_allowed(allow: &str) -> Response {
    Response {
        status: 405,
        headers: vec![("allow".to_string(), allow.to_string())],
        body: Vec::new(),
    }
}

fn is_get_like(method: &str) -> bool {
    method == "GET" || method == "HEAD"
}

fn route(request: &Request, state: &Arc<AppState>) -> (Response, bool) {
    let path = request.raw_path.as_str();
    let method = request.method.as_str();

    // The session page.
    if path == "/" {
        return match method {
            "GET" | "HEAD" => {
                let session = state.session.lock().unwrap();
                (
                    Response::new(
                        200,
                        "text/html; charset=utf-8",
                        session.render_page().into_bytes(),
                    ),
                    false,
                )
            }
            "POST" => handle_post(request, state),
            _ => (method_not_allowed("GET,HEAD,POST"), false),
        };
    }

    // Generated script with the deck's TeX macros spliced in.
    if path == "/script.js" {
        if !is_get_like(method) {
            return (method_not_allowed("GET,HEAD"), false);
        }
        let mut script = String::from("let MACROS = {};\n");
        for (name, definition) in &state.macros {
            script.push_str(&format!("MACROS['{}'] = '{}';\n", name, definition));
        }
        script.push('\n');
        script.push_str(SCRIPT_JS);
        return (
            Response::new(200, "text/javascript", script.into_bytes()),
            false,
        );
    }

    if path == "/style.css" {
        if !is_get_like(method) {
            return (method_not_allowed("GET,HEAD"), false);
        }
        return (
            Response::new(200, "text/css", STYLE_CSS.as_bytes().to_vec())
                .with_header("cache-control", "public, max-age=604800, immutable"),
            false,
        );
    }

    let katex_asset: Option<(&[u8], &str)> = match path {
        "/katex/katex.css" => Some((KATEX_CSS, "text/css")),
        "/katex/katex.js" => Some((KATEX_JS, "text/javascript")),
        "/katex/mhchem.js" => Some((MHCHEM_JS, "text/javascript")),
        _ => None,
    };
    if let Some((bytes, content_type)) = katex_asset {
        if !is_get_like(method) {
            return (method_not_allowed("GET,HEAD"), false);
        }
        return (
            Response::new(200, content_type, bytes.to_vec())
                .with_header("cache-control", "public, max-age=604800, immutable"),
            false,
        );
    }

    if let Some(rest) = path.strip_prefix("/katex/fonts/") {
        if rest.is_empty() {
            return (fallback_404(), false);
        }
        if !is_get_like(method) {
            return (method_not_allowed("GET,HEAD"), false);
        }
        let Ok(name) = percent_decode(rest) else {
            return (invalid_url_response(), false);
        };
        return match font_asset(&name) {
            Some(bytes) => (
                Response::new(200, "font/woff2", bytes.to_vec())
                    .with_header("cache-control", "public, max-age=604800, immutable"),
                false,
            ),
            None => (plain_404(true), false),
        };
    }

    if let Some(rest) = path.strip_prefix("/file/") {
        if rest.is_empty() {
            return (fallback_404(), false);
        }
        if !is_get_like(method) {
            return (method_not_allowed("GET,HEAD"), false);
        }
        let Ok(decoded) = percent_decode(rest) else {
            return (invalid_url_response(), false);
        };
        return (serve_file(&state.root, &decoded), false);
    }

    (fallback_404(), false)
}

fn serve_file(root: &Path, rel_str: &str) -> Response {
    let rel = Path::new(rel_str);
    let bad = rel.is_absolute()
        || rel
            .components()
            .any(|c| matches!(c, Component::ParentDir | Component::RootDir | Component::Prefix(_)));
    if bad {
        return plain_404(false);
    }
    let full: PathBuf = root.join(rel);
    let Ok(metadata) = std::fs::symlink_metadata(&full) else {
        return plain_404(false);
    };
    if !metadata.file_type().is_file() {
        return plain_404(false);
    }
    match std::fs::read(&full) {
        Ok(bytes) => Response::new(200, file_content_type(&full), bytes),
        Err(_) => plain_404(false),
    }
}

fn file_content_type(path: &Path) -> &'static str {
    let ext = path
        .extension()
        .map(|e| e.to_string_lossy().to_ascii_lowercase())
        .unwrap_or_default();
    match ext.as_str() {
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "svg" => "image/svg+xml",
        "mp3" => "audio/mpeg",
        "wav" => "audio/wav",
        "ogg" => "audio/ogg",
        "mp4" => "video/mp4",
        "webm" => "video/webm",
        _ => "application/octet-stream",
    }
}

const ACTIONS: [&str; 8] = [
    "Reveal", "Undo", "End", "Forgot", "Hard", "Good", "Easy", "Shutdown",
];

fn form_error(status: u16, message: String) -> Response {
    Response::new(status, "text/plain; charset=utf-8", message.into_bytes())
}

fn handle_post(request: &Request, state: &Arc<AppState>) -> (Response, bool) {
    let content_type = request.header("content-type").unwrap_or("");
    if !content_type.starts_with("application/x-www-form-urlencoded") {
        return (
            form_error(
                415,
                "Form requests must have `Content-Type: application/x-www-form-urlencoded`".to_string(),
            ),
            false,
        );
    }
    if request.body.len() > 2 * 1024 * 1024 {
        return (
            form_error(
                413,
                "Failed to buffer the request body: length limit exceeded".to_string(),
            ),
            false,
        );
    }
    let action = match parse_form_action(&request.body) {
        Ok(action) => action,
        Err(message) => return (form_error(422, message), false),
    };
    let shutdown = {
        let mut session = state.session.lock().unwrap();
        let db = state.db.lock().unwrap();
        match session.handle_action(&db, action) {
            Ok(shutdown) => shutdown,
            Err(e) => {
                eprintln!("error: error: {}", e);
                false
            }
        }
    };
    let response = Response {
        status: 303,
        headers: vec![("location".to_string(), "/".to_string())],
        body: Vec::new(),
    };
    (response, shutdown)
}

fn parse_form_action(body: &[u8]) -> std::result::Result<Action, String> {
    let body_str = String::from_utf8_lossy(body);
    let mut action_value: Option<String> = None;
    for pair in body_str.split('&') {
        if pair.is_empty() {
            continue;
        }
        let (key_raw, value_raw) = match pair.split_once('=') {
            Some((k, v)) => (k, v),
            None => (pair, ""),
        };
        let key = url_decode_component(key_raw);
        if key != "action" {
            continue;
        }
        if action_value.is_some() {
            return Err(
                "Failed to deserialize form body: duplicate field `action`".to_string(),
            );
        }
        action_value = Some(url_decode_component(value_raw));
    }
    let Some(value) = action_value else {
        return Err("Failed to deserialize form body: missing field `action`".to_string());
    };
    match value.as_str() {
        "Reveal" => Ok(Action::Reveal),
        "Undo" => Ok(Action::Undo),
        "End" => Ok(Action::End),
        "Forgot" => Ok(Action::Forgot),
        "Hard" => Ok(Action::Hard),
        "Good" => Ok(Action::Good),
        "Easy" => Ok(Action::Easy),
        "Shutdown" => Ok(Action::Shutdown),
        other => Err(format!(
            "Failed to deserialize form body: action: unknown variant `{}`, expected one of {}",
            other,
            ACTIONS
                .iter()
                .map(|a| format!("`{}`", a))
                .collect::<Vec<_>>()
                .join(", ")
        )),
    }
}

fn url_decode_component(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'+' => {
                out.push(b' ');
                i += 1;
            }
            b'%'
                if i + 2 < bytes.len()
                    && (bytes[i + 1] as char).is_ascii_hexdigit()
                    && (bytes[i + 2] as char).is_ascii_hexdigit() =>
            {
                out.push(u8::from_str_radix(&s[i + 1..i + 3], 16).unwrap_or(b'%'));
                i += 3;
            }
            b => {
                out.push(b);
                i += 1;
            }
        }
    }
    String::from_utf8_lossy(&out).into_owned()
}
RS
"}

