                    println!("{}", serde_json::to_string_pretty(&stats).unwrap());
                }
                _ => {
                    eprintln!("HTML output is not implemented yet.");
                }
            }
            Ok(())
        }
        Some(("orphans", sub)) => match sub.subcommand() {
            Some(("list", orphans_sub)) => {
                let (collection, db) =
                    open_collection(orphans_sub.get_one::<String>("directory"))?;
                let orphans = orphan_hashes(&collection, &db)?;
                for hash in &orphans {
                    println!("{}", hash);
                }
                Ok(())
            }
            Some(("delete", orphans_sub)) => {
                let (collection, db) =
                    open_collection(orphans_sub.get_one::<String>("directory"))?;
                let orphans = orphan_hashes(&collection, &db)?;
                for hash in &orphans {
                    db.delete_card(*hash)?;
                }
                for hash in &orphans {
                    println!("{}", hash);
                }
                Ok(())
            }
            _ => unreachable!(),
        },
        Some(("export", sub)) => {
            let (collection, db) = open_collection(sub.get_one::<String>("directory"))?;
            let mut cards: Vec<Card> = collection.cards.values().cloned().collect();
            for card in &mut cards {
                card.performance = db.get_performance(card.hash)?;
            }
            let sessions = db.get_sessions()?;
            let export = Export { cards, sessions };
            let json = serde_json::to_string_pretty(&export).unwrap();
            match sub.get_one::<String>("output") {
                Some(output) => {
                    std::fs::write(output, json)?;
                }
                None => {
                    println!("{}", json);
                }
            }
            Ok(())
        }
        Some(("drill", sub)) => {
            let (mut collection, db) = open_collection(sub.get_one::<String>("directory"))?;
            let started_at = types::Timestamp::now();
            let hashes: Vec<types::Hash> = collection.cards.keys().cloned().collect();
            db.add_cards_if_missing(&hashes, started_at)?;
            for card in collection.cards.values_mut() {
                card.performance = db.get_performance(card.hash)?;
            }
            let answer_controls = match sub
                .get_one::<String>("answer-controls")
                .map(|s| s.as_str())
            {
                Some("binary") => drill::AnswerControls::Binary,
                _ => drill::AnswerControls::Full,
            };
            let port = *sub.get_one::<u16>("port").unwrap_or(&8000);
            let options = drill::DrillOptions {
                card_limit: sub.get_one::<usize>("card-limit").copied(),
                new_card_limit: sub.get_one::<usize>("new-card-limit").copied(),
                from_deck: sub.get_one::<String>("from-deck").cloned(),
                bury_siblings: sub
                    .get_one::<bool>("bury-siblings")
                    .copied()
                    .unwrap_or(true),
                answer_controls,
                port,
            };
            let session = drill::DrillSession::new(collection, &options, started_at);
            if session.is_empty() {
                println!("No cards due today.");
                return Ok(());
            }
            let host = sub
                .get_one::<String>("host")
                .cloned()
                .unwrap_or_else(|| "127.0.0.1".to_string());
            let open_browser = sub
                .get_one::<bool>("open-browser")
                .copied()
                .unwrap_or(true);
            let listener = std::net::TcpListener::bind((host.as_str(), port))?;
            server::serve(listener, session, db, open_browser, &host, port)
        }
        _ => unreachable!(),
    }
}

fn orphan_hashes(collection: &Collection, db: &Db) -> Result<Vec<types::Hash>> {
    let db_hashes = db.get_all_card_hashes()?;
    let deck_hashes: std::collections::BTreeSet<types::Hash> =
        collection.cards.keys().cloned().collect();
    Ok(db_hashes.difference(&deck_hashes).cloned().collect())
}

