fn html_block_start_mode(line: &str) -> Option<(HtmlBlockKind, bool)> {
    let s = unindented(line)?;
    let t = s.as_str();
    if !t.starts_with('<') {
        return None;
    }
    let lower = t.to_ascii_lowercase();
    for tag in ["script", "pre", "style", "textarea"] {
        let open = format!("<{}", tag);
        if lower.starts_with(&open) {
            let after = &lower[open.len()..];
            if after.is_empty()
                || after.starts_with(' ')
                || after.starts_with('\\t')
                || after.starts_with('>')
                || after.starts_with("/>")
            {
                return Some((HtmlBlockKind::UntilClose(tag.to_string()), true));
            }
        }
    }
    if t.starts_with("<!--") {
        return Some((HtmlBlockKind::UntilText("-->".to_string()), true));
    }
    if t.starts_with("<?") {
        return Some((HtmlBlockKind::UntilText("?>".to_string()), true));
    }
    if t.starts_with("<![CDATA[") {
        return Some((HtmlBlockKind::UntilText("]]>".to_string()), true));
    }
    if t.starts_with("<!") && t[2..].chars().next().is_some_and(|c| c.is_ascii_uppercase()) {
        return Some((HtmlBlockKind::UntilText(">".to_string()), true));
    }
    // CommonMark HTML block condition 6: a block-level tag.
    if let Some(kind) = block_tag_html_start(t) {
        return Some((kind, true));
    }
    // Condition 7: a line consisting of one complete tag.  This cannot
    // interrupt a paragraph.
    let trimmed = t.trim();
    if let Some(end) = parse_inline_html_tag(trimmed) {
        if end == trimmed.len() {
            return Some((HtmlBlockKind::UntilBlank, false));
        }
    }
    None
}

fn block_tag_html_start(t: &str) -> Option<HtmlBlockKind> {
    let bytes = t.as_bytes();
    let mut i = 1usize;
    if bytes.get(i) == Some(&b'/') {
        i += 1;
    }
    let start = i;
    if i >= bytes.len() || !bytes[i].is_ascii_alphabetic() {
        return None;
    }
    while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'-') {
        i += 1;
    }
    let name = t[start..i].to_ascii_lowercase();
    const BLOCK_TAGS: &[&str] = &[
        "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption",
        "center", "col", "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt",
        "fieldset", "figcaption", "figure", "footer", "form", "frame", "frameset", "h1", "h2",
        "h3", "h4", "h5", "h6", "head", "header", "hr", "html", "iframe", "legend", "li", "link",
        "main", "menu", "menuitem", "nav", "noframes", "ol", "optgroup", "option", "p", "param",
        "search", "section", "summary", "table", "tbody", "td", "tfoot", "th", "thead", "title",
        "tr", "track", "ul",
    ];
    if !BLOCK_TAGS.contains(&name.as_str()) {
        return None;
    }
    match bytes.get(i) {
        None => Some(HtmlBlockKind::UntilBlank),
        Some(b' ') | Some(b'\\t') | Some(b'\\n') | Some(b'>') => Some(HtmlBlockKind::UntilBlank),
        Some(b'/') if bytes.get(i + 1) == Some(&b'>') => Some(HtmlBlockKind::UntilBlank),
        _ => None,
    }
}

