fn label_contains_link(label: &str, refs: &HashMap<String, LinkDef>, enable_math: bool) -> bool {
    let bytes = label.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        let ch = label[i..].chars().next().unwrap();
        match ch {
            '\\\\' => {
                let next = label[i + 1..].chars().next();
                if next.is_some_and(|c| c.is_ascii_punctuation()) {
                    i += 1 + next.unwrap().len_utf8();
                } else {
                    i += 1;
                }
            }
            '`' => {
                let run = count_run(label, i, '`');
                if let Some(end) = find_code_close(label, i + run, run) {
                    i = end;
                } else {
                    i += run;
                }
            }
            '$' if enable_math => {
                if let Some((consumed, _)) = try_parse_math(label, i) {
                    i += consumed;
                } else {
                    i += 1;
                }
            }
            '<' => match parse_angle(label, i) {
                Some((_, end, Some(_))) => return true,
                Some((_, end, None)) => i = end,
                None => i += 1,
            },
