                if let Some((end, _, _, _)) = try_parse_link(label, i + 1, refs) {
                    i = end;
                } else {
                    i += 1;
                }
            }
            '[' => {
                if try_parse_link(label, i, refs).is_some() {
                    return true;
                }
                i += 1;
            }
            _ => {
                i += ch.len_utf8();
            }
        }
    }
    false
}

